    "uniqueMechanic": "Перл (Pearl, 4.6) — Десятое Каменное Сердце КММ и первый полноценный сустейн Пути Радости (Elation). Простыми словами её работа строится вокруг трёх уникальных механик, проверенных по Prydwen и официальной базе HSR. Первая механика — «Сертифицированный Хит» (Certified Banger) и щит-буфер «Отталкивание» (Repellency): в отличие от всех остальных агентов Радости, у которых стаки Certified Banger сгорают через 2 хода, стаки самой Перл (максимум до 50 стаков) НЕ ИСТЕКАЮТ по времени! Каждый 1 стак Certified Banger на Перл создаёт 200 ед. буфера Repellency (до 10 000 ед. буфера!), который перехватывает 60% любого урона по союзникам до потери их ХП и даёт 2 автоматических воскрешения за бой (с восстановлением 50% ХП). Вторая механика — «Эстетический Архетип» и Дополнительный Ход: Сверхспособность Перл (180 энергии) назначает вашего главного ДД «Эстетическим Архетипом» и в зависимости от числа агентов Радости в отряде (1/2/3) продвигает его действие на 10%/15%/30%, а при 4 агентах Радости (или 3 агентах на E1!) дарит этому керри мгновенный ДОПОЛНИТЕЛЬНЫЙ ХОД и заливает +30 стаков Certified Banger! Третья механика — «Глубокое обучение» (Deep Learning, 3 заряда после Ульты): пока оно активно, Перл раздаёт всему отряду +20% Пробития всех резистов (All-Type RES PEN) и +50% Сопротивления эффектам (След A2), а её усиленная Базовая атака бьёт всех врагов, лечит команду и наносит 240% Ледяного урона Радости (Elation DMG), ПОЛНОСТЬЮ КОПИРУЯ Силу Атаки, Крит. шанс, Крит. урон и Радость вашего главного керри!",
