      "ult": "Оценка глубин души (Сверхспособность [Ult], 180 энергии): Наносит 120% DEF Ледяного урона всем врагам, даёт Перл +20 Certified Banger и +3 заряда «Глубокого обучения», а также выбирает союзника «Эстетическим Архетипом»: при 1/2/3 агентах Радости продвигает его действие на 10%/15%/30%, а при 4 агентах Радости (3 на E1) даёт ему полноценный Дополнительный Ход и заливает +30 Certified Banger!",
      "talent": "Изящество из стойкости (Талант): Конвертирует каждый стак Certified Banger Перл (макс. 50, не исчезают по ходам) в 200 ед. буфера Repellency, блокирующего 60% входящего урона по отряду. При 2 / 3 / 4 агентах Радости в отряде повышает Elation всех союзников на +10% / +20% / +60%! Дважды за бой спасает союзников от смертельного удара, восстанавливая 50% Max HP.",
