    "tipsAndTraps": "1) Почему Перл собирают 0% Крит. шанса и 0% Крит. урона? Потому что её усиленная Базовая атака (240% Ледяного Elation DMG) полностью игнорирует собственные криты Перл и берёт 100% Крит. шанса, Крит. урона, Атаки и Радости того керри, на ком висит метка «Эстетический Архетип»! Вкладывайте все сабстаты только в Скорость (160.1+ SPD) и Защиту (4000+ DEF). 2) Важная тонкость тайминга Ульты (из обзора Prydwen): помните, что стаки Certified Banger на ваших дамагерах (кроме Эванесции на E6 и Авантюрина • Волнореза) длятся ровно 2 их хода. Если бездумно продвинуть ход керри Ультой Перл в момент, когда у него нет энергии или Панчлайна, он быстрее прокрутит ход и потеряет старые стаки Certified Banger. Поэтому жмите Ульту Перл сразу ПОСЛЕ «Мгновения Ахи» или перед готовым бурстом керри! 3) Секрет энергии: обязательно нажимайте Ульту вашего керри ПОСЛЕ Ульты Перл — тогда След A6 мгновенно вернёт Перл половину шкалы энергии (90 из 180 ед.!).",
