      "critRate": "По Prydwen её След A6 («Impromptu Hum») повышает Крит. шанс самой Зарянки • Саммеретто и её Мемоспрайта на +50% в бою! С 4pc сетом Спасителя (+8% КШ) и планаркой Амфореуса (+8% КШ) в меню нужно собрать НЕ БОЛЕЕ 42% КШ!",
