    "uniqueMechanic": "Рин Тосака (Rin Tohsaka, 4.4) — Квантовый 5★ агент Эрудиции из коллаборации Fate/stay night [UBW], которая может играть как мощный самостоятельный гиперкерри ИЛИ как идеальный второй ДД в паре с бесплатным Арчером! Простыми словами её уникальная механика (проверенная по Prydwen) состоит из трёх частей: 1) Накопление «Самоцветов» (Gems) от траты SP: каждый раз, когда любой союзник в отряде тратит Очки Навыков (особенно Арчер, выстреливающий до 5 раз за ход!), Рин заряжает свои магические Самоцветы. Накопив Самоцветы, её обычный Навык превращается в усиленный каст «Залп Самоцветов» и запускает 5-ударную Бонус-атаку «Атака Великого Гандра»! 2) Безумный След A2 («Magus Successor»): просто находясь в отряде, Рин увеличивает максимальный потолок Очков Навыков команды на +2 (вместе с Арчером и Искоркой лимит доходит до 9–11 SP!), а при входе в бой навсегда повышает свою Силу Атаки на +150% и Квантовое пробитие резистов (Quantum RES PEN) на +15% — причём если в отряде есть Арчер, то АРЧЕР ТОЖЕ ПОЛУЧАЕТ эти +150% ATK и +15% Квантового RES PEN на весь бой! 3) Ядерная Сверхспособность «An Gal Ta Ki Gal Šè» (160 энергии): наносит 600% ATK по главной цели и 200% ATK по всем остальным врагам, вешает на всех врагов +20% Уязвимости к урону (Vulnerability) на 2 хода и мгновенно восстанавливает +1 SP!",
    "skills": {
      "basic": "Бацзицюань (Базовая [Q]): Наносит Квантовый урон в ближнем бою, генерирует +1 SP и 1 заряд Самоцвета.",
      "skill": "Магия Самоцветов / Концентрированный Залп (Навык [E]): Поглощает заряженные Самоцветы, наносит взрывной Квантовый урон по всем врагам и запускает подготовку к 5-ударной Бонус-атаке «Великого Гандра».",
      "ult": "Ан Галь Та Ки Галь Ше (Сверхспособность [Ult], 160 энергии): Обрушивает древнее проклятие богини Иштар: наносит 600% ATK Квантового урона выбранному боссу и 200% ATK всем остальным врагам, повышает получаемый всеми врагами урон на +20% на 2 хода и восстанавливает +1 Очко Навыков (SP)!",
      "talent": "Конверсионный Заряд (Талант): За каждое потраченное союзниками Очко Навыков (SP) заряжает Самоцветы. После усиленного Навыка или серии выстрелов союзника выпускает 5-ударную Бонус-атаку «Great Gandr Attack» (и Меч Зелретча).",
      "technique": "Эксперимент Второй Магии (Техника): В начале боя заряжает стартовые Самоцветы, генерирует +1 SP и наносит Квантовый урон.",
      "summon_or_elation": "Самоцветный Меч Зелретча (Усиленная Бонус-атака): Разрезает пространство многократным Квантовым взрывом, восстанавливая энергию Рин и активируя синергию с Арчером.",
      "traces": "След A2 («Magus Successor»): Увеличивает макс. лимит SP отряда на +2; при входе в бой даёт самой Рин (и Арчеру, если он в отряде!) +150% ATK и +15% Квантового RES PEN! След A4 («Perfect Honor Student»): При входе в бой и после усиленного Навыка повышает Скорость Рин на +20% (+20.8 SPD) на 3 хода! След A6: Даёт +12% Крит. шанса в бою и ускоряет откат Ульты при трате Самоцветов."
    },
    "rotation": "Техника перед боем → Ход 1 (134+ SPD в меню = 155+ SPD в бою со Следом A4!): Навык [E] → Искорка тянет Арчера и жмёт Ульту → Арчер выпускает серию спиральных стрел, мгновенно заряжая Самоцветы Рин → 5-ударная Бонус-атака Рин «Великий Гандр» → Сверхспособность Рин «An Gal Ta Ki Gal Šè» [Ult] (600% в босса + +20% уязвимости врагов + возврат 1 SP)!",
    "tipsAndTraps": "1) Почему связка Арчер + Рин Тосака + Искорка настолько сильна? Потому что След A2 Рин бесплатно дарит Арчеру +150% ATK и +15% Квантового RES PEN просто за присутствие в отряде, а её Ульта добавляет ещё +20% Уязвимости на босса и возвращает +1 SP прямо под пулемётную стойку Арчера! 2) Спидтюнинг Рин: её След A4 автоматически даёт ей +20% Скорости (+20.8 SPD) со старта боя и после каждого усиленного Навыка, поэтому при 134 SPD в меню она в бою летает на 155+ SPD!",
