      "e2": "E2: Сразу даёт +5 «Интереса» на старте боя и удваивает множитель «Врат Вавилона» по главной цели.",
      "e4": "E4: Даёт +20% Восстановления энергии (ERR).",
      "e6": "E6: Множитель отскоков «Энума Элиш» вырастает на 80%, весь отряд получает +20% RES PEN и до +300% Крит. урона на Ульту.",
      "rec": "В паре с Сэйбер и Хохо работает отлично уже на E0S0; E1 превращает его в командного деф-шредера (33% игнора DEF на весь отряд)."
