    "rarity": 5,
    "statWhy": {
      "spd": "По данным Prydwen и Следа A2 («False Ending Speedrun»): при Скорости ≥160 Серебряный Волк LV.999 получает +50% Радости (Elation), а за каждую 1 ед. SPD свыше 160 — ещё по +2% Elation вплоть до ЖЁСТКОГО КАПА 260 SPD в бою (= +250% Elation!). Поэтому ей жизненно необходимы Сапоги на Скорость (160+ SPD в меню) и скоростные баффы в бою до 200–260 SPD!",
      "critRate": "След A4 даёт +15% Крит. шанса в бою, а планарка «Панклорд: Нулевой уровень» — ещё +12% КШ при 20 Панчлайна (суммарно +27% скрытого КШ!). Поэтому в меню до боя собирайте ровно 70–73% КШ (= 100% КШ в бою).",
      "critDmg": "Весь её Мнимый урон Радости (Elation DMG) в режиме «God Mode ON!» и «Мгновении Ахи» критует по общей формуле критов — стремитесь к 180%+ КУ в меню и 280%+ КУ в бою.",
      "scale": "Хотя её базовая атака невысока, все множители ударов вне «Мгновения Ахи» зависят от ATK%, а Планарная сфера на ATK% усиливает и обычные удары, и косвенные скейлы лучше сферы на Мнимый урон%.",
      "elation": "Главный стат Волка LV.999! Складывается из сферы/верёвки/конуса (60%+ в меню) и гигантской конверсии Следа A2 (+250% Elation на капе 260 SPD в бою).",
      "err": "Сверхспособность Серебряного Волка LV.999 («God Mode ON!») работает от накопленного Панчлайна и чит-кодов, поэтому стат ERR% ей не нужен (0% пользы)."
    }
