      "critDmg": "Крит. урон — двойной стат для Эванесции! Её Талант конвертирует 20% от её общего Крит. урона напрямую в показатель Радости (Elation%) без верхнего потолка (300% КУ в бою = +60% бесплатной Elation!).",
