    "uniqueMechanic": "Первопроходец (Радость, Электрический, 4.2) — бесплатный S-тир саппорт со всеми 6 Эйдолонами из сюжета Планаркадии! Позволяет закрыть условие «3 или 4 персонажа Радости в отряде» для Перл, Эванесции и Серебряного Волка LV.999 без затрат звёздного нефрита. Раздаёт всему отряду +35% Elation, +10% Крит. шанса (на E6) и +36% Крит. урона, активно генерирует очки Панчлайна базовыми атаками (+SP) и ускоряет наступление «Мгновения Ахи».",
