      "basic": "Шутка за 300 кредитов (Базовая): Наносит Электрический урон, генерирует +1 SP и заливает +15 очков Панчлайна.",
      "skill": "Режиссёрский कट (Навык): Создаёт сцену «Прайм-Тайм» на 3 хода (+35% Elation всем союзникам и +10% Крит. шанса на E6) и заливает +30 Панчлайна.",
      "ult": "Смех за кадром! (Сверхспособность, 130 энергии): Наносит АоЕ Электрический Elation DMG, заливает +40 Панчлайна и продвигает действие всего отряда на 20%.",
      "talent": "Любимец публики (Талант): Передаёт всем союзникам 15% от собственного Крит. урона Первопроходца + 12% фиксированно (~36% КУ).",
      "technique": "Спойлер к финалу (Техника): В начале боя сразу включает сцену «Прайм-Тайм» на 3 хода и даёт +25 Панчлайна.",
      "summon_or_elation": "Гэг с битой (Навык Радости / Elation Skill): В Мгновение Ахи бьёт всех врагов Электрическим уроном Радости и восстанавливает 1 Очко Навыков.",
      "traces": "След A2 («On Cloud Nine» — КАП АТАКИ 2200 ATK): За каждые 200 ед. Силы Атаки (ATK) Первопроходца свыше 1000 его показатель Радости (Elation) повышается на +10%, вплоть до ЖЁСТКОГО КАПА +60% Elation ровно при 2200 ATK! След A4 («Screw It, We Ball»): Повышает Крит. шанс ГГ на +15% и восстанавливает +1 Очко Навыков (SP) после Сверхспособности (которая также баффает выбранного керри на +50% Крит. урона!). След A6: Первое применение Навыка Радости даёт +15 Панчлайна и активирует командный сет."
