    "tipsAndTraps": "1) Главный секрет механики и сборки: Поскольку все 6 эйдолонов ГГ Радости выдаются бесплатно за прохождение Планаркадии, всегда учитывайте его E6 (+10% Крит. шанса всему отряду в бою!), когда считаете кап КШ для своего керри. 2) Точный контроль Крит. шанса по Prydwen: В бою получает +15% КШ от Следа A4 («Screw It, We Ball»), +18% КШ от 4pc Прорицателя и +10% КШ от бесплатного E6 (суммарно +43% скрытого КШ!). Поэтому в меню нужно всего ~57% КШ. 3) Оптимальный спидтюнинг: 160.1+ SPD в меню для активации 4pc Прорицателя (+18% КШ и +10% Elation команде) и частой генерации Панчлайна и SP.",
