    "uniqueMechanic": "Эшвейл (Ashveil, 4.1) — Электрический 5★ агент Охоты, который совмещает колоссальный соло-таргетный урон Бонус-атак с лучшей в игре командной аурой для любых FUA-отрядов! Простыми словами его механика (проверенная по Prydwen) работает так: 1) Метка «Наживки» (Bait — -40% Защиты врага!): Навык и Сверхспособность Эшвейла вешают на выбранного босса постоянную метку «Наживки», которая снижает Защиту (DEF) цели на 40%! При смерти врага с «Наживкой» метка автоматически перепрыгивает на следующего врага. 2) Командная аура Крит. урона (След A6): просто находясь на поле боя, Эшвейл постоянно повышает Крит. урон ВСЕХ союзников на +40%, а Крит. урон всех Бонус-атак (FUA) союзников — на дополнительные +80% (суммарно +120% Крит. урона для всех Бонус-атак отряда!)! 3) 12 стаков «Обжорства» (Gluttony, 1 стак со старта): каждый раз, когда союзники проводят Бонус-атаки по «Наживке», Эшвейл отвечает собственной Бонус-атакой Таланта (300% ATK) и копит стаки «Обжорства» (до 12 стаков). Когда Эшвейл нажимает Сверхспособность (400% ATK), он немедленно запускает Усиленную Бонус-атаку Таланта, которая поглощает до 12 стаков «Обжорства» (по 4 стака за тик), получает до +200% Бонуса урона от Следа A4 и наносит дополнительные 800% ATK (итого 1100% ATK за одну Бонус-атаку после Ульты!).",
    "skills": {
      "basic": "Когти прививают приличия (Базовая [Q]): Наносит 100% ATK Электрического урона 1 цели (+1 SP).",
      "skill": "Плеть карает зло (Навык [E]): Накладывает на цель метку «Наживки» (Bait: снижает Защиту цели на 40%!), наносит 200% ATK Электрического урона (300% ATK, если на цели уже была «Наживка»!), даёт +1 стак «Обжорства» и продвигает ход.",
      "ult": "Банкет: Ненасытный аппетит (Сверхспособность [Ult], 130 энергии): Вешает «Наживку» (-40% DEF), наносит 400% ATK Электрического урона, даёт +2 стака «Обжорства» и НЕМЕДЛЕННО запускает Усиленную Бонус-атаку Таланта (до 1100% ATK множителя на 12 стаках «Обжорства»!).",
      "talent": "Злоба, вражда и возмездие (Талант): Когда союзники атакуют «Наживку», Эшвейл проводит Бонус-атаку (300% ATK) и получает стаки «Обжорства» (до 12 стаков). После Сверхспособности Усиленная Бонус-атака тратит стаки «Обжорства» (кратно 4), добавляя по +200% ATK множителя за каждые 4 стака (на 12 стаках = 300% + 600% + бонус = до 1100% ATK!).",
      "technique": "Пожри, о отвратительная длань (Техника): В начале боя накладывает «Наживку» (-40% DEF), наносит Электрический урон и даёт +4 стака «Обжорства».",
      "summon_or_elation": "Тандем с Напарником «Первого Номера»: Вместе с теневым компаньоном «The First» преследует «Наживку» после каждой серии Бонус-атак союзников (Авантюрин • Волнорез, Мортенакс Блэйд, Фэйсяо, Трибби).",
      "traces": "След A2: Повышает Крит. шанс Эшвейла на +15% против целей с «Наживкой» и автоматически переносит «Наживку» при смерти врага. След A4: За каждый потраченный стак «Обжорства» повышает Бонус урона финального удара (до +200% DMG Boost на 12 стаках!). След A6: Пока Эшвейл на поле, Крит. урон всех союзников повышен на +40%, а Крит. урон всех Бонус-атак (FUA) союзников повышен на дополнительные +80% (итого +120% КУ для FUA!)."
    },
    "rotation": "Техника перед боем (Наживка -40% DEF и 5 стаков Обжорства со старта!) → Ход 1: Навык [E] по Наживке (300% ATK) → Бонус-атаки союзников (Авантюрин • Волнорез / Мортенакс Блэйд / Фэйсяо) вызывают ответные Бонус-атаки Эшвейла и добирают 12 стаков «Обжорства» → Сверхспособность Эшвейла [Ult] (400% ATK + мгновенная Усиленная Бонус-атака на 1100% ATK со +200% Бонуса урона!)!",
    "tipsAndTraps": "1) Главное правило Сверхспособности Эшвейла (по Prydwen): старайтесь нажимать Ульту Эшвейла тогда, когда счётчик «Обжорства» (Gluttony) равен 8 или 12 стакам! Усиленная Бонус-атака тратит стаки пачками по 4 штуки (4 / 8 / 12) — на 12 стаках вы получаете максимальный 1100% ATK множитель и +200% Бонуса урона! 2) Благодаря Следу A6 (+120% КУ для всех FUA отряда) и метке «Наживки» (-40% DEF) Эшвейл может играть как соло-гиперкерри, так и в дуал-керри с Фэйсяо или Авантюрином • Волнорезом!",
