    "rarity": 5,
    "statWhy": {
      "spd": "Главный стат баффера Яо Гуан по Prydwen! Её След A2 («Amaze-In Grace») требует минимум 120 SPD (+30% Elation) и за каждую 1 ед. SPD выше 120 даёт ещё +1% Elation вплоть до КАПА 320 SPD (+230% Elation!). Так как её Зона передаёт 20% от общей Elation самой Яо Гуан ВСЕМ союзникам, сборка 165+ SPD в меню (200+ SPD в бою) даёт и 3 хода в 0-м цикле, и максимальный командный бафф Радости!",
      "critRate": "Набор «Прорицатель дальних пределов» при ≥160 SPD даёт ей +18% Крит. шанса, а собственная Зона — ещё +15% КШ (суммарно +33% КШ!). В меню собирайте ~67% КШ для 100% критов её Навыка Радости.",
      "critDmg": "След A4 («Poised and Sated») автоматически заливает самой Яо Гуан +60% Крит. урона в бою, позволяя её АоЕ Навыку Радости наносить внушительный личный урон.",
      "scale": "HP% и ATK% обеспечивают выживаемость (4200+ HP) и базовый урон перьев.",
      "elation": "Через Зону Яо Гуан раздаёт всему отряду 20% от своей собственной Elation (при 185% Elation в бою у Яо Гуан это +37% чистой Elation каждому союзнику сверх базовых баффов!).",
      "err": "Стоимость Сверхспособности Яо Гуан — 180 энергии! Чтобы удерживать Зону и +20% All-Type RES PEN без простоев, верёвка на ERR% (+19.4%) + планарка Лушака/Вонвак (+5%) строго обязательны (124.4% ERR)."
    }
