    "uniqueMechanic": "Спаркси (Sparxie, 4.0) — альтер-эго Искорки на Пути Радости (Огненный), которая работает как взрывной SP-пулемётчик и одновременно мощнейший баффер Крит. урона для отрядов Радости! Простыми словами её механика (проверенная по Prydwen) строится вокруг трёх вещей: 1) «Накрутка Вовлечённости» (Engagement Farming) и «Ажиотаж» (Thrill): нажав Боевой Навык, Спаркси запускает стрим и превращает свою Базовую атаку в «Расцвет! Победитель забирает всё». Прямо перед ударом вы можете многократно нажимать кнопку «Engagement Farming» (до 20 раз за ход!), тратя по 1 Очку Навыков (SP) или по 1 стаку бесплатного «Ажиотажа» (Thrill — каждый потраченный стак Thrill игра засчитывает как реальную трату 1 SP для всех пассивок Искорки и Яо Гуан!). За каждые 4/8/12 потраченных SP/Thrill за ход Спаркси обрушивает дополнительный ливень Огненного Elation DMG и заливает кучу Панчлайна! 2) Жёсткий кап Атаки (След A2 «Sweet! Punchline Signing» — КАП 3600 ATK): за каждые 100 ед. ATK свыше 2000 Спаркси получает +5% Elation, достигая максимума +80% Elation ровно при 3600 ATK! 3) Командный бафф Крит. урона (След A6 «Frenzy! Palette of Truth and Lies»): за каждую 1 единицу Панчлайна, имеющуюся у отряда, Спаркси повышает Крит. урон ВСЕХ СОЮЗНИКОВ на +8% (вплоть до +80% Крит. урона всей команде уже при 10+ очках Панчлайна!).",
    "skills": {
      "basic": "Кошка проглотила огненный язык / Расцвет! Победитель забирает всё (Базовая / Усиленная [Q]): В режиме стрима (после Навыка) не даёт SP, но поглощает все вложенные за этот ход заряды «Engagement Farming» (SP + Thrill), нанося взрывной Огненный урон по 3 целям + каскад дополнительных рикошетов Огненного Elation DMG!",
      "skill": "Бум! Спарксикл взрывает чат (Навык [E]): Запускает Прямой эфир, переводит Базовую атаку в усиленный режим, даёт стаки «Thrill» (бесплатные заменители SP) и открывает кнопку «Engagement Farming» для многократного вливания SP в текущий ход.",
      "ult": "Вечеринка на максимуме и камера пишет! (Сверхспособность [Ult], 130 энергии): Наносит АоЕ Огненный урон + Огненный Elation DMG (60% всем врагам), генерирует +2 Панчлайна (+дополнительно 2/4/8 Панчлайна и 1/1/4 стака «Thrill» при 1/2/3+ агентах Радости от Следа A4!).",
      "talent": "Монетизация контента (Талант): Пока у Спаркси есть Certified Banger, использование «Engagement Farming» и Сверхспособности вызывает дополнительные взрывы Огненного Elation DMG и начисляет стаки «Thrill».",
      "technique": "Фарм вовлечённости (Техника): Ослепляет врагов на 10 сек.; при входе в бой наносит Огненный урон всем врагам и сразу восстанавливает +2 Очка Навыков (SP) для команды!",
      "summon_or_elation": "Перегрузка сигнала: Великий Бис! (Навык Радости / Elation Skill): В «Мгновение Ахи» наносит АоЕ Огненный Elation DMG (50% всем врагам + 20 рикошетов по случайным врагам!) и даёт Спаркси +4 стака «Thrill» (4 бесплатных SP на следующий стрим!).",
      "traces": "След A2 (КАП АТАКИ 3600 ATK): За каждые 100 ед. ATK свыше 2000 повышает Elation Спаркси на +5% (максимум +80% Elation ровно при 3600 ATK!). След A4: При 1/2/3+ агентах Радости в отряде Сверхспособность дополнительно даёт 2/4/8 Панчлайна и 1/1/4 стака «Thrill». След A6 (КАП +80% КУ ОТРЯДУ): За каждое 1 очко Панчлайна у отряда повышает Крит. урон ВСЕХ СОЮЗНИКОВ на +8% (максимум +80% Крит. урона при 10+ Панчлайна!)."
    },
    "rotation": "Техника перед боем (+2 SP команде со старта!) → В паре с быстрой Искоркой (которая заливает SP и даёт лимит 7 SP) или в качестве саб-ДД под Волка LV.999: Сверхспособность [Ult] (даёт до +4 бесплатных стаков «Thrill» и +10 Панчлайна = мгновенно включает +80% КУ всему отряду!) → Навык [E] → Влейте накопленные стаки «Thrill» и свободные SP в «Engagement Farming» → Усиленная Базовая атака [Q]!",
    "tipsAndTraps": "1) Как играть Спаркси в двух разных ролях? Если Спаркси — ваш главный ДД (в отряде со старой Искоркой, Яо Гуан и Перл), сливайте в её «Engagement Farming» по 8–12 SP/Thrill за ход. Если же Спаркси стоит вторым номером к Серебряному Волку LV.999 или Эванесции, тратьте на её стриме только бесплатные стаки «Thrill» (полученные от её Ульты и Навыка Радости), не отнимая реальные SP у главного керри! 2) Обязательно соберите ровно 3600 Силы Атаки (ATK), чтобы полностью закрыть кап Следа A2 (+80% Elation).",
