    "uniqueMechanic": "Эон ★ Аха (Анонс 4.7) — вершина пути Радости (Квантовый). Создаёт на шкале ходов собственную сущность «Театр Абсурда» и позволяет всему отряду активировать «Мгновение Ахи» (Aha Instant) дважды за цикл, конвертируя избыточный Панчлайн в Квантовый Elation DMG и Истинный урон (True DMG). По расчётам Prydwen и официальной базы HSR: Базовый скейл «Эон ★ Аха» строится от Силы Атаки (3400+ ATK в меню → 4600+ ATK в бою). След A2: +15% КШ всему отряду Радости. След A4: +60% Elation в бою. След A6: После Ульты восстанавливает 2 Очка Навыков.",
