    "tipsAndTraps": "1) Главный секрет механики и сборки: Даёт +15% КШ себе и союзникам Радости — не собирайте выше 73% КШ в меню (с планаркой Панклорда +12% КШ в бою будет ровно 100%). 2) Точный контроль Крит. шанса по Prydwen: Для «Эон ★ Аха» ориентир в меню до боя — 70% Крит. шанса: с учётом встроенных следов (След A2: +15% КШ всему отряду Радости) и боевых баффов реликвий/саппортов это выводит героя ровно на 100% Крит. шанса в бою без перекапа. 3) Оптимальный спидтюнинг: Целевой брейкпоинт 135 SPD в меню (155 SPD в бою) выводит «Эон ★ Аха» на 2 полных действия в 0-м цикле (150 AV) и идеально синхронизируется с продвигателями хода по схеме «-1 SPD». След A2: +15% КШ всему отряду Радости.",
