    "uniqueMechanic": "Георгина (The Dahlia, 3.8) — финальный пазл премиального отряда Суперпробития (Светлячок + Фуга + Георгина + Линша), заменяющий старую Жуань Мэй или ГГ Гармонии! Она накладывает на врагов «Чёрный Георгин Погибели», который позволяет наносить 50% урона Суперпробития ДАЖЕ ПО НЕПРОБИТЫМ ВРАГАМ (до снятия полоски стойкости!), повышает эффективность пробития уязвимости на 50%, режет защиту на 24% и даёт +20% RES PEN.",
    "skills": {
      "basic": "Шипы увядания (Базовая): Огненный урон + срез стойкости (+1 SP).",
      "skill": "Сад Чёрного Георгина (Навык): Накладывает на всех врагов «Чёрный Георгин» (-24% DEF, +30% уязвимости к пробитию) и даёт союзникам +50% эффективности пробития уязвимости на 3 хода.",
      "ult": "Реквием Герцога Инферно (Сверхспособность, 130 энергии): Наносит АоЕ Огненный урон, задерживает действие врагов на 35% и включает 120% множитель Суперпробития на 2 хода (работает на 50% силы даже по врагам с целой полоской стойкости!).",
      "talent": "Пепел памяти (Талант): Раздаёт всему отряду +60% Эффекта пробития и +10% Скорости.",
      "technique": "Аромат полночи (Техника): В начале боя сразу накладывает «Чёрный Георгин» и снимает 30 ед. стойкости со всех врагов независимо от их типа уязвимости.",
      "summon_or_elation": "Взрыв бутона: При пробитии уязвимости врага или экзо-стойкости Фуги вызывает дополнительный огненный взрыв Суперпробития.",
      "traces": "След A2 («Yet Another Funeral» — Конверсия Пробития Георгины отряду): В начале боя и при получении исцеления/щита от союзника Георгина повышает Эффект пробития ВСЕХ остальных союзников на (24% от Эффекта пробития Георгины + 50%) на 3 хода (при 250% BE у Георгины она заливает +110% Эффекта пробития всей команде!)! След A4 («Lament, Lost Soul»): Каждая 2-я Бонус-атака Таланта восстанавливает +1 Очко Навыков (SP). След A6 («Outgrow the Old, Espouse the New»): При наложении уязвимости на врага Скорость повышается на +30% на 2 хода!"
    },
    "rotation": "Техника перед боем → Ход 1 (160.1+ SPD): Сверхспособность [Ult] → Базовая атака [Q] (+SP) → Снятие двойной стойкости вместе с Фугой, Светлячком и Линшой!",
    "tipsAndTraps": "1) Главный секрет механики и сборки: В меню достаточно собрать ~160% Эффекта пробития, так как её собственный Талант (+60% BE) и Лотос Кальпагни (+40% BE) в бою легко доведут показатель выше капа 220–250%. 2) Ключевой порог масштабирования: ГЛАВНЫЙ БАФФ ГЕОРГИНЫ ПО PRYDWEN (След A2 «Yet Another Funeral»): в начале боя и при каждом получении лечения/щита от союзника (Линша / Галлахер) Георгина повышает Эффект пробития ВСЕХ остальных союзников на (24% от собственного Эффекта пробития Георгины + 50%) на 3 хода! При 250% BE у Георгины в меню (330% в бою) она заливает Светлячку/Раппе/Бутхиллу свыше +115%–130% Эффекта пробития и позволяет бить Суперпробитием прямо сквозь белую полоску стойкости! 3) Оптимальный спидтюнинг: В меню достаточно 145–160 SPD, потому что её След A6 («Outgrow the Old, Espouse the New») при каждом импланте уязвимости (от Светлячка, Бутхилла или самой Георгины) даёт +30% Скорости на 2 хода (разгоняя её до 185+ SPD в бою!).",
