      "scale": "ГЛАВНЫЙ БАФФ ГЕОРГИНЫ ПО PRYDWEN (След A2 «Yet Another Funeral»): в начале боя и при каждом получении лечения/щита от союзника (Линша / Галлахер) Георгина повышает Эффект пробития ВСЕХ остальных союзников на (24% от собственного Эффекта пробития Георгины + 50%) на 3 хода! При 250% BE у Георгины в меню (330% в бою) она заливает Светлячку/Раппе/Бутхиллу свыше +115%–130% Эффекта пробития и позволяет бить Суперпробитием прямо сквозь белую полоску стойкости!",
