      "spd": "134+ SPD в меню (или <95 SPD при сборке через 4pc сет Поэта).",
      "critRate": "Внимание на перекап! По данным Prydwen След A2 Темени («Dark the Night, Still the Moon») постоянно даёт ей и её Мемоспрайту «Иви» +35% Крит. шанса в бою! С 4pc сетом Спасителя (+8% КШ) в меню собирайте НЕ БОЛЕЕ 57% КШ (а с сетом Поэта +32% КШ — не более 33% КШ в меню!).",
      "critDmg": "ГЛАВНЫЙ БАФФ ТЕМЕНИ: её Навык передаёт 24% от собственного Крит. урона Темени ВСЕМ мемоспрайтам союзников (включая Дракона Кастории!), а След A6 даёт ещё +50% / +65% КУ всем мемоспрайтам при 3 / 4 героях Памяти в отряде!",
