    "uniqueMechanic": "Дань Хэн • Освободитель Пустошей (Permansor Terrae, 3.6) — уникальный Физический щитовик Сохранения, чьи Щиты и баффы скейлятся от его СИЛЫ АТАКИ (ATK), а не от Защиты! Навыком он связывает главного ДД узами «Bondmate», заливая ему 15% от собственной Силы Атаки Дань Хэна, и призывает для этого ДД персонального «Дракона Души» (Souldragon, SPD 165)! Главное чудо: поскольку Дракон Души прикрепляется к вашему ДД как ЕГО собственное призывное существо, ЛЮБОЙ ДД в паре с Дань Хэном PT начинает получать полный 80%-й бафф от Воскресенья и +48% КУ от Банановой планарки!",
    "skills": {
      "basic": "Эгида жизни (Базовая): Наносит 110% ATK Физического урона (2 удара).",
      "skill": "Земля Всеобъемлющая (Навык): Делает союзника «Связанным Узами» (Bondmate) и накладывает на весь отряд суммируемый Щит (до 300% прочности) в размере 21.2% ATK + 445 на 3 хода.",
      "ult": "Зенит Дракона не знает сожалений (Сверхспособность, 135 энергии): Наносит 330% ATK Физического урона всем врагам, обновляет командный Щит и усиливает «Дракона Души» на 2 действия: Дракон проводит АоЕ Бонус-атаку (88% ATK Дань Хэна + 88% ATK Связанного союзника его стихией!).",
      "talent": "Добродетель обретает форму (Талант): Призывает «Дракона Души» (начальная Скорость 165) для носителя «Bondmate». В каждый свой ход Дракон снимает по 1 дебаффу со всех союзников и накладывает дополнительный командный Щит!",
      "technique": "Раскол земли (Техника): Оглушает врагов и вешает «Bondmate» на активного керри. На старте боя автоматически применяет Навык на керри бесплатно (0 SP)!",
      "summon_or_elation": "Призывной «Дракон Души» (Souldragon, SPD 165): Считается призывным существом вашего керри! Когда керри атакует, Дракон продвигает свой ход на 15%, а Дань Хэн получает +6 энергии.",
      "traces": "След A2 (Empyreanity): Повышает ATK носителя «Bondmate» на 15% от общей Силы Атаки Дань Хэна (~650 плоской ATK!). След A4 (Sylvanity): В начале боя продвигает действие Дань Хэна на 40%; каждая атака Bondmate даёт +6 энергии Дань Хэну и двигает Дракона на 15%. След A6 (Sublimity): Усиленный Дракон дополнительно бьёт самого толстого врага на 40% ATK вашего керри."
    },
    "rotation": "Техника перед боем (переключитесь на главного ДД — бесплатный Навык и Дракон Души сразу появятся на старте!) → Ход 1 (с 40% продвижением со старта): Базовая атака [Q] (+1 SP) → Сверхспособность [Ult] → Автоматические ходы Дракона Души (чистят дебаффы, стакают щиты и бьют от статов керри!).",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Секретная комбо-механика: так как «Дракон Души» привязывается к носителю «Bondmate», даже герой без родного саммона (например, Фаенон, Арчер, Ахерон или Сэйбер) считается «персонажем с призывным существом»! Это значит, что Воскресенье с ним продвигает на 100% И вашего керри, И Дракона Души, а также даёт полные +80% урона! Внимание: собирайте Дань Хэну Тело и Сферу строго на ATK%, а не на DEF%. 2) Ключевой порог масштабирования: ГЛАВНАЯ ОСОБЕННОСТЬ ДАНЬ ХЭНА PT: это единственный щитовик Сохранения, чьи Щиты И командный бафф зависят от СИЛЫ АТАКИ (ATK% — 3800–4400+ ATK), а НЕ от Защиты! Его След A2 передаёт союзнику с узами «Bondmate» 15% от общей Силы Атаки самого Дань Хэна (~650 плоской ATK!) и прикрепляет к этому керри «Дракона Души» (благодаря чему Воскресенье даёт вашему керри полные +80% урона как призывателю!). 3) Оптимальный спидтюнинг: 143–160+ SPD в меню (в начале боя След A4 продвигает его на 40%, а его призывной «Дракон Души» имеет собственную скорость 165 SPD и сам чистит дебаффы и обновляет щиты!).",
    "eidolons": {
      "e1": "E1: Сверхспособность восстанавливает 1 Очко Навыков (SP) и даёт носителю «Bondmate» +18% Пробития всех резистов (All-Type RES PEN) на 3 хода!",
      "e2": "E2: Ульта даёт +2 дополнительных усиленных действия Дракону, продвигает Дракона на 100% и удваивает его урон и щиты (200%).",
      "e4": "E4: Носитель «Bondmate» получает на 20% меньше урона.",
      "e6": "E6: Все враги получают +20% уязвимости к урону, Bondmate игнорирует 12% DEF и наносит +330% ATK АоЕ урона при Ульте Дань Хэна.",
      "rec": "На E0S0 — лучший щитовик в истории игры, полностью SP-позитивный за счёт Техники и Дракона (165 SPD). E1 делает его ещё и баффером на +18% RES PEN и генератором SP!"
    },
