      "scale": "ГЛАВНАЯ ОСОБЕННОСТЬ ДАНЬ ХЭНА PT: это единственный щитовик Сохранения, чьи Щиты И командный бафф зависят от СИЛЫ АТАКИ (ATK% — 3800–4400+ ATK), а НЕ от Защиты! Его След A2 передаёт союзнику с узами «Bondmate» 15% от общей Силы Атаки самого Дань Хэна (~650 плоской ATK!) и прикрепляет к этому керри «Дракона Души» (благодаря чему Воскресенье даёт вашему керри полные +80% урона как призывателю!).",
      "err": "Верёвка на ERR% (119.4%–124.4% с Лушакой) позволяет каждые 3 хода усиливать Дракона Души на двойной АоЕ-удар от статов вашего керри.",
      "critRate": "Ориентир Крит. шанса в меню для Дань Хэн • Освободитель Пустошей: 50% КШ, чтобы с учётом боевых бонусов следов, реликвий и саппортов достичь стабильных 100% КШ в бою без перекапа.",
      "critDmg": "Ориентир Крит. урона в меню для Дань Хэн • Освободитель Пустошей: 130%+ КУ (в бою разгоняется до 240%+ КУ под баффами отряда)."
