    "uniqueMechanic": "Гисиленса (3.5) возродила архетип Периодического урона (DoT) в тройке Кафка + Чёрный Лебедь + Гисиленса! Она открывает подводное поле «Бездна Сирены», в котором ВСЕ статусы периодического урона (Шок Кафки, Аркана Лебедя и её собственное «Абиссальное Кровотечение») могут наносить фиксированные критические удары (150% множителя) и срабатывают повторно при каждом действии врага или детонации Кафки, игнорируя 25% Защиты!",
    "skills": {
      "basic": "Аккорд глубины (Базовая): Физический урон и 100% базовый шанс наложить «Абиссальное Кровотечение».",
      "skill": "Соната Алого Прилива (Навык): Бьёт 3 цели, накладывает 3 стака «Абиссального Кровотечения» и снижает защиту врагов на 25% на 3 хода.",
      "ult": "Хор Затонувшей Империи (Сверхспособность, 130 энергии): Открывает зону «Бездна Сирены» на 3 хода (+30% получаемого врагами DoT-урона и возможность DoT-эффектов наносить 150% крит. урон!) и мгновенно детонирует все DoT на 120% от их силы.",
      "talent": "Песнь кровоточащих струн (Талант): За каждый 1% EHR до 120% повышает собственный урон и DoT-множитель на 0.6% (до +72% при 120% EHR!).",
      "technique": "Зов сирены (Техника): В начале боя сразу открывает зону «Бездна Сирены» и вешает «Абиссальное Кровотечение» на всех врагов.",
      "summon_or_elation": "Резонанс Кровотечения: Суммируется с 4pc сетом Узника (18% игнора DEF + 25% от Навыка Гисиленсы = 43% среза защиты для всей DoT-команды!).",
      "traces": "След A2 («The Fiddle of Pearls»): В начале боя автоматически разворачивает Зону (-25% DEF врагов) и восстанавливает +1 Очко Навыков (SP) при каждом открытии Зоны! След A4 («The Banquet of Foam»): Сверхспособность Гисиленсы (всего 110 энергии!) МГНОВЕННО ДЕТОНИРУЕТ все эффекты Периодического урона (DoT) на врагах в размере 150% от их исходного урона! След A6 («The Strings of Conquest» — КАП EHR 120%): За каждые 10% Шанса попадания эффектов (EHR) свыше 60% повышает весь наносимый Гисиленсой урон на +15%, вплоть до ЖЁСТКОГО КАПА +90% Бонуса урона ровно при 120% EHR!"
    },
    "rotation": "Техника перед боем (зона активна!) → Ход 1: Навык [E] (-25% DEF) → Сверхспособность [Ult] (детонация) → Ход Кафки (двойная детонация всех DoT и Арканы Чёрного Лебедя!).",
    "tipsAndTraps": "Следите за двумя порогами в меню: 120% EHR (для капа Следа A2) и 3600 ATK в бою (для капа планарного сета «Пиршество у моря» / Revelry by the Sea).",
