    "uniqueMechanic": "Керидра (3.5) — лучший узкоспециализированный саппорт Гармонии для Фаенона (и других гиперкерри, бьющих Навыком: Анакса, Арчер, Химеко • Нова)! Она жалует союзнику титул «Военная Заслуга» (Military Merit → Peerage / Дворянство), дающий +20 плоской Скорости в бою, +60% Крит. урона Навыка и уникальную механику «Переворот» (Coup de Main): раз за цикл выбранный керри автоматически ДУБЛИРУЕТ применение своего усиленного Навыка (например, Фаенон в стойке Касланы сбрасывает ДВА метеорита подряд за один ход без траты стаков!).",
    "skills": {
      "basic": "Рокировка королевы (Базовая): Ветряной урон + 1 стак Зарядов (+1 SP).",
      "skill": "Указ о возвышении (Навык): Наделяет союзника титулом «Военная Заслуга» (+20 плоской Скорости на 3 хода, +45% ATK от атаки Керидры и накопление зарядов до 6 для «Дворянства»).",
      "ult": "Шах и Мат Империи (Сверхспособность, 130 энергии): Наносит АоЕ Ветряной урон, даёт +2 заряда «Военной Заслуги» и продвигает ход выбранного керри.",
      "talent": "Закон Победителя (Талант): На 6 зарядах «Военная Заслуга» превращается в «Дворянство» (Peerage): следующий Навык керри получает +60% Крит. урона, +16% RES PEN и срабатывает ДВАЖДЫ подряд (Coup de Main)!",
      "technique": "Королевский гамбит (Техника): В начале боя автоматически вешает «Военную Заслугу» на первого героя и даёт +2 заряда (и 1 стак Ядра Пламени для Фаенона!).",
      "summon_or_elation": "Сохранение баффа в территории Фаенона: Все баффы Керидры и счётчик «Дворянства» продолжают работать даже тогда, когда Фаенон изгоняет союзников с поля боя!",
      "traces": "След A2 («Veni» — КАП АТАКИ 4000 ATK): За каждые 100 ед. Силы Атаки (ATK) Керидры свыше 2000 её Крит. урон повышается на +18%, вплоть до ЖЁСТКОГО КАПА +360% Крит. урона ровно при 4000 ATK (попутно максимизируя её залив 24% ATK на главного керри!)! След A4 («Vidi»): Повышает Крит. шанс Керидры на +100% (гарантированные криты при 0% КШ в меню!). След A6 («Vici»): При применении Навыка Скорость самой Керидры И выбранного союзника с «Военной Заслугой» повышается на +20 плоских единиц на 3 хода!"
    },
    "rotation": "Техника перед боем → Ход 1: Навык [E] на Фаенона / керри (+20 SPD цели!) → Сверхспособность [Ult] → Керри получает «Дворянство» и кастует двойной усиленный Навык подряд!",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Керидра заливает вашему керри ровно +20 плоской Скорости в бою! Это значит, что если вы хотите, чтобы ваш ДД в бою имел 135 Скорости (под Воскресенье 134 SPD), вам нужно собрать ДД в меню всего 115 Скорости (115 + 20 = 135 SPD в бою!), а сапоги надеть на ATK%! 2) Ключевой порог масштабирования: СТРОГИЙ КАП КЕРИДРЫ ПО PRYDWEN — ровно 4000 ATK! Её След A2 («Veni») за каждые 100 ATK свыше 2000 даёт ей +18% Крит. урона вплоть до ЖЁСТКОГО КАПА +360% КУ ровно при 4000 ATK, а также передаёт 24% от её ATK вашему главному керри (~960 плоской ATK!) и позволяет керри ДУБЛИРОВАТЬ свой Навык дважды подряд (Coup de Main)! 3) Оптимальный спидтюнинг: По Prydwen Керидре нужно всего 140.1 SPD в меню, потому что её След A6 («Vici») даёт +20 плоской Скорости И самой Керидре (140.1 + 20 = 160.1 SPD в бою!), И выбранному керри с «Военной Заслугой»!",
    "eidolons": {
      "e1": "E1: Навык Керидры даёт цели +15 энергии (или +2 стака Ядра Пламени Фаенону!), а дублируемый Навык игнорирует 36% DEF.",
      "e2": "E2: Урон носителя «Военной Заслуги» повышается ещё на 40%.",
      "e4": "E4: Множитель Ульты Керидры увеличивается на 240%.",
      "e6": "E6: Даёт носителю титула +20% All-Type RES PEN и 300% доп. урона от каждого удара.",
      "rec": "Идеальный сигнатурный напарник для Фаенона, Анаксы и Арчера."
    },
