      "spd": "По Prydwen Керидре нужно всего 140.1 SPD в меню, потому что её След A6 («Vici») даёт +20 плоской Скорости И самой Керидре (140.1 + 20 = 160.1 SPD в бою!), И выбранному керри с «Военной Заслугой»!",
