      "scale": "СТРОГИЙ КАП КЕРИДРЫ ПО PRYDWEN — ровно 4000 ATK! Её След A2 («Veni») за каждые 100 ATK свыше 2000 даёт ей +18% Крит. урона вплоть до ЖЁСТКОГО КАПА +360% КУ ровно при 4000 ATK, а также передаёт 24% от её ATK вашему главному керри (~960 плоской ATK!) и позволяет керри ДУБЛИРОВАТЬ свой Навык дважды подряд (Coup de Main)!",
