    "uniqueMechanic": "Фаенон (3.4) НЕ ИМЕЕТ шкалы Энергии! Вместо неё он копит 12 стаков «Ядра Пламени» (Coreflame, макс. 15): он получает +2 стака от своего Навыка и по +1 стаку КАЖДЫЙ РАЗ, когда любой союзник выбирает Фаенона целью своего направленного баффа/навыка/ульты (Воскресенье, Керидра, Кирена, Искорка, Броня, Дань Хэн PT)! Набрав 12 стаков, Фаенон перевоплощается в титана «Каслану», разворачивает Территорию, ИЗГОНЯЕТ всех трёх союзников с поля боя (замораживая длительность всех наложенных на него баффов!) и получает 8 собственных внеочередных ходов бога с Физическим имплантом уязвимости на всех врагов, иммунитетом к контролю и падением Звёздных Метеоритов!",
    "skills": {
      "basic": "Рассветный клинок / Удар Творения (Базовая): Обычная даёт 1 стак. В форме Касланы бьёт 3 цели и даёт 2 заряда «Уничтожения».",
      "skill": "Клятва Элизии / Падение Небесного Свода (Навык): Обычный даёт 2 «Ядра Пламени». В форме Касланы тратит 4 заряда «Уничтожения» и обрушивает гигантский Звёздный Метеорит (до 1170% ATK Физического урона!), который Керидра может продублировать дважды подряд!",
      "ult": "Тот, кто несёт мир на плечах (Сверхспособность, 12 Ядер Пламени): Трансформируется в Каслану, убирает союзников с поля боя (активируя максимальный бонус +36% урона от планарки «Аркадия сплетённых снов» за 3 отсутствующих союзников!), замораживает таймеры всех баффов и даёт 8 ходов с фиксированной скоростью.",
      "talent": "Сосуд Пламени (Талант): Каждый раз, когда союзник применяет навык или ульту на Фаенона, Фаенон получает +1 «Ядро Пламени» и +30% Крит. урона. При получении лечения или щита его урон возрастает ещё на 45%!",
      "technique": "Заря над Охемой (Техника): Мгновенно побеждает обычных врагов в мире, а в бою с боссами даёт +3 «Ядра Пламени», +2 SP и 25 энергии всему отряду.",
      "summon_or_elation": "Контратака Титана (Стойка Души): В форме Касланы может принудительно заставить всех врагов немедленно атаковать его, снижая входящий урон на 75% и выпуская сокрушительную АоЕ-контратаку.",
      "traces": "След A2: Когда союзник даёт Фаенону залив Энергии (например, Ульта Воскресенья, Кирены, Хохо или Тинъюнь), этот залив конвертируется в дополнительное «Ядро Пламени»! След A4: При получении лечения или щита (Гиацина / Дань Хэн PT / Хохо) Фаенон получает +45% Бонуса урона на 4 хода. След A6: Вход в форму Касланы и выход из неё дают +50% ATK (до +100% ATK!)."
    },
    "rotation": "Техника перед боем (3 Ядра) → Фаенон (135 SPD) жмёт Навык [E] (+2 Ядра) → Керидра жмёт Навык и Ульту на Фаенона (+2 Ядра) → Воскресенье (134 SPD) тянет Фаенона Навыком и заливает Ульту (+3 Ядра) → Кирена / Дань Хэн PT даёт бафф (+2 Ядра = 12 Ядер!) → Сверхспособность Фаенона [Ult] со всеми баффами внутри 0-го цикла!",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Почему планарка «Аркадия сплетённых снов» (Arcadia of Woven Dreams) и сет «Капитан волнореза» созданы специально под Фаенона? Когда Фаенон жмёт Ульту, он убирает 3 союзников с поля — на поле остаётся 1 герой вместо 4, и Аркадия мгновенно даёт максимальные +36% итогового урона! А поскольку таймеры баффов в Ульте Фаенона НЕ ТИКАЮТ, все 1-ходовые и 2-ходовые баффы Воскресенья, Керидры, Брони и сета Капитана (+48% ATK) висят на нём все 8 ходов формы Касланы! 2) Точный контроль Крит. шанса по Prydwen: 75–80% КШ в меню (с Воскресеньем +20% КШ = 100% КШ в бою на все 8 ходов формы титана Касланы!). 3) Оптимальный спидтюнинг: Два варианта по Prydwen: 1) 135–136 SPD в меню (или всего 115–116 SPD в меню с сапогами на ATK%, если в отряде есть Керидра, заливающая +20 плоской Скорости в бою!) под Воскресенье 134 SPD. 2) Базовая скорость с ATK% сапогами под гиперскоростных бафферов 160+ SPD.",
