      "e2": "E2 (ИМБА!): Даёт +20% Физического RES PEN, а применение Метеорита на 4 стаках «Уничтожения» даёт МГНОВЕННЫЙ ДОПОЛНИТЕЛЬНЫЙ ХОД (удвоение числа метеоритов за Ульту!).",
