      "critDmg": "След A4 даёт до +60% Крит. урона при применении Навыка (а с Гильгамешем в отряде След A6 Гильгамеша заливает Сэйбер ещё +120% КУ и +120% ATK благодаря её Ульте 240 энергии!).",
