    "uniqueMechanic": "Гиацина (3.3) — первый целитель Пути Памяти и незаменимый двигатель команд Кастории, Темени, Мидея и Блэйда! Она призывает пухлого крылатого пегаса-мемоспрайта «Малышку Ику» (Little Ica) и включает состояние «После Дождя», которое увеличивает Максимальное ХП всего отряда на +30% + 600 ед.! Каждый раз, когда союзник теряет ХП от врага или собственных навыков, Ика мгновенно тратит немного своего ХП и автоматически лечит отряд, а затем выстреливает радужным АоЕ-лучом со 100% гарантированным Крит. шансом, чей урон равен суммарному исцелению! А за каждый 1 ед. Скорости Гиацины сверх 200 её лечение и ХП растут ещё сильнее!",
    "skills": {
      "basic": "Капля росы (Базовая): Ветряной урон от Max HP + исцеление.",
      "skill": "Любовь сквозь радугу (Навык): Призывает «Малышку Ику», снимает по 1 дебаффу со всех союзников и массово лечит всю команду и всех мемоспрайтов.",
      "ult": "Мы летим в сумерки! (Сверхспособность, 140 энергии): Исцеляет всех союзников и мемоспрайтов и включает состояние «После Дождя» на 3 хода: увеличивает Max HP всего отряда на 30% + 600 и заставляет Ику атаковать после каждого действия Гиацины.",
      "talent": "Крылья рассвета (Талант): Когда любой союзник теряет ХП, «Малышка Ика» автоматически расходует 4% своего ХП и мгновенно исцеляет этого союзника (мгновенно заряжая Новые Бутоны Кастории!). Урон Ики увеличивается на 80% за каждое исцеление (до +240%).",
      "technique": "Погода шепчет (Техника): В начале боя лечит всех союзников и увеличивает их Max HP на 20%.",
      "summon_or_elation": "Мемоспрайт «Малышка Ика» (Little Ica): Имеет +50% Сопротивления эффектам, впитывает всё исцеление отряда и конвертирует его в огромный АоЕ Ветряной урон со 100% Крит. шансом.",
      "traces": "След A2: Крит. шанс Гиацины и «Малышки Ики» повышается на +100% (гарантированные криты всегда!). След A4: Навык и Ульта снимают по 1 дебаффу со ВСЕХ союзников и дают +50% Effect RES. След A6: Если Скорость Гиацины в бою превышает 200, Max HP её и Ики растёт на 20%, а за каждую 1 ед. SPD свыше 200 (вплоть до 400 SPD!) Бонус лечения увеличивается на 1%."
    },
    "rotation": "Техника перед боем → Ход 1 (200+ SPD в бою): Навык [E] → Сверхспособность [Ult] (включает +30% Max HP на весь отряд и запускает залп Ики) → Далее чередуйте Навык [E] и Базовую атаку [Q] (3 хода в 0-м цикле при 200+ SPD!).",
    "tipsAndTraps": "Чтобы пробить порог 200 Скорости в бою (для Следа A6 и 3 действий в 0-м цикле), вам НЕ нужно собирать 200 SPD голыми сабстатами! У Гиацины 110 базовой скорости + 14 из следов + 25 сапоги = 149 SPD. Добавьте 4pc сет «Воительница солнца и грозы» (+12% SPD = +13.2) и 2pc планарку «Гигантское древо» (+6% SPD = +6.6) — это уже 168.8 SPD! Остаётся поймать всего ~31 SPD в сабстатах (или взять 5★ конус из Магазина Герты / сигну).",
    "eidolons": {
      "e1": "E1: Бонус Max HP от состояния «После Дождя» вырастает с 30% до 80%! Кроме того, каждая атака союзника дополнительно лечит его на 8% ХП Гиацины.",
      "e2": "E2: Когда ХП любого союзника снижается, его Скорость повышается на 30% на 2 хода!",
      "e4": "E4: За каждую 1 ед. SPD свыше 200 Гиацина и Ика получают ещё +2% Крит. урона.",
      "e6": "E6: Даёт всему отряду +20% Пробития всех резистов (All-Type RES PEN) и сохраняет накопленный урон Ики.",
      "rec": "Абсолютный must-have для Кастории, Темени и Мидея; с сигной S1 становится лучшим сустейном и для Блэйда, и для Ахерон (сигна вешает дебафф!)."
    },
