    "uniqueMechanic": "Цифер (3.3) — молниеносная Квантовая кошка-воровка Небытия (базовая скорость 113 + следы на SPD!). Просто находясь на поле боя, она автоматически повышает получаемый ВСЕМИ врагами урон на +40% (Vulnerability)! Кроме того, она отмечает главного босса как «Постоянного Клиента» (Regular Customer) и записывает в свою копилку 24% от ВСЕГО урона, который ваша команда наносит этому боссу (и 16% по остальным врагам). Когда вы нажимаете Сверхспособность Цифер, она разбивает копилку и обрушивает всю украденную сумму обратно в босса в виде чистого Истинного Урона (True DMG)!",
