    "uniqueMechanic": "Кастория (3.2) — самый надёжный и разрушительный Квантовый гиперкерри Пути Памяти в игре! Она НЕ ТРАТИТ Очков Навыков (0 SP) и НЕ ИСПОЛЬЗУЕТ Энергию: вместо этого она копит заряд «Нового Бутона» (Newbud, до 100%) за каждую единицу ХП, которую теряет ИЛИ исцеляет любой союзник и мемоспрайт на поле! На 100% заряда она призывает колоссального Мемоспрайта — Дракона Смерти «Крыло Нижнего Мира: Полидевксию» (Netherwing: Pollux, 165 SPD), разворачивает Территорию (-20% ВСЕХ резистов врагов!) и выжигает поле боя серией дыханий Дракона и совместным взрывом крыльев! Кроме того, её глобальная пассивка спасает павших союзников от смерти даже со склада аккаунта!",
    "skills": {
      "basic": "Скорбь волн (Базовая): Квантовый урон от Max HP.",
      "skill": "Молчание шёлковой бабочки / Объятия когтей (Навык / Усиленный): НЕ ТРАТИТ SP! Потребляет 30% текущего ХП всех союзников (заряжая Новый Бутон) и наносит АоЕ Квантовый урон от Max HP. Когда Дракон на поле, превращается в совместный удар Кастории и Дракона по всем врагам!",
      "ult": "Рёв погибели и зарождения (Сверхспособность, 100% Нового Бутона): Мгновенно призывает Дракона Смерти «Полидевксию» (SPD 165), продвигает его действие на 100% и открывает Территорию «Потерянный Нижний Мир» (-20% All-Type RES врагов!).",
      "talent": "Ладонь скорби (Талант): За каждый 1% потерянного ХП союзников Кастория заряжает Новый Бутон и получает до +60% Бонуса урона.",
      "technique": "Ода вечному покою (Техника): В начале боя сразу призывает Дракона Смерти «Полидевксию» и открывает Территорию без ожидания зарядки!",
      "summon_or_elation": "Мемоспрайт «Дракон Смерти: Полидевксия» (SPD 165): В свой ход может дышать пламенем смерти СКОЛЬКО УГОДНО РАЗ ПОДРЯД (тратя по 25% своего ХП за каждое дыхание и усиливая множитель с каждым залпом), а на 25% ХП или 3-м ходе взрывается крыльями на 6 отскоков Квантового урона и исцеляет весь отряд!",
      "traces": "След A2: Оверхил (избыточное исцеление) союзников от Гиацины, Галлахера или Лочи тоже конвертируется в заряд «Нового Бутона»! След A4: Пока ХП Кастории ≥50%, её Скорость в бою увеличивается на +40% (не влияет на проверку сета Поэта ДО БОЯ!). След A6: Каждое дыхание Дракона увеличивает урон следующего дыхания на 30%."
    },
    "rotation": "Техника перед боем (Дракон уже на поле!) → Гиацина и Темень ходят, сливают и лечат ХП → Ход Дракона: прожимайте Дыхание 3–4 раза подряд до взрыва крыльев (или оставьте 25% ХП для совместного Навыка Кастории, если Гиацина тут же отхилит Дракона обратно до 100%!) → Навык Кастории [E] (0 SP) → Новый призыв Дракона!",
    "tipsAndTraps": "Два главных секрета сборки Кастории: 1) В меню ДО БОЯ её Скорость обязана быть СТРОГО МЕНЬШЕ 95 (`<95 SPD`)! Базовая скорость Кастории — 95, а 4pc сет «Поэт элегии разрушения» снижает скорость на 8% (до 87.4 SPD в меню) и даёт ей И Дракону гигантские +32% Крит. шанса! Если вы поймаете больше 3 роллов скорости в сабстатах и превысите 95 SPD в меню, вы потеряете +32% КШ! 2) НИКОГДА не ставьте к ней щитовиков (Авантюрин, Гепард), потому что щиты блокируют потерю ХП и останавливают зарядку Дракона! Её лучшие друзья — Гиацина, Темень, Зарянка • Саммеретто, Кирена и Трибби.",
    "eidolons": {
      "e1": "E1: Враги с ХП ≤80% / ≤50% получают на 20% / 40% больше финального урона от Дракона и совместного Навыка.",
      "e2": "E2 (ОГРОМНЫЙ СПАЙК!): При призыве Дракона Кастория получает 2 стака «Пылкой Воли» (2 бесплатных дыхания Дракона без траты его ХП!) и продвигает собственное действие на 100% для мгновенного совместного Навыка!",
      "e4": "E4: Повышает входящее исцеление всего отряда на 20% (быстрее заряжает Дракона!).",
      "e6": "E6: +20% Квантового RES PEN, Дракон игнорирует тип уязвимости и даёт +3 дополнительных отскока при взрыве крыльев.",
      "rec": "На E0S1 с Гиациной и Теменью — самая живучая и мощная АоЕ/Соло пачка игры."
    },
