    "uniqueMechanic": "Анакса (3.2) — гениальный алхимик-универсал Эрудиции: каждая его атака накладывает на врагов недостающие им типы уязвимостей (без проверки EHR!), а Сверхспособность мгновенно вешает на всех врагов ВСЕ 7 СТИХИЙНЫХ УЯЗВИМОСТЕЙ игры! Когда на враге висит 5+ уязвимостей, любая атака Анаксы автоматически вызывает БЕСПЛАТНОЕ ПОВТОРНОЕ ПРИМЕНЕНИЕ его Навыка (0 SP, двойной каст за ход!). А его След A6 адаптивно меняет его роль: если Анакса — единственный Эрудит в отряде, он получает +140% личного Крит. урона (режим Соло-Гиперкерри); если в отряде 2+ Эрудита (например, с Великой Гертой), он раздаёт +50% Бонуса урона всему отряду!",
