    "uniqueMechanic": "Трибби (3.1) — самый универсальный саппорт-дамагер Гармонии, усиливающий АБСОЛЮТНО ЛЮБОЙ ТИП УРОНА благодаря двум самым редким множителям в формуле HSR: Навык даёт +24% Пробития всех резистов (All-Type RES PEN), а Зона Сверхспособности повышает получаемый врагами урон на +30% (Vulnerability) и концентрирует дополнительный квантовый урон по самому живучему боссу на поле! Более того, после Сверхспособности КАЖДОГО из трёх союзников Трибби запускает ракетную АоЕ Бонус-атаку, а её След A4 увеличивает её собственное ХП на 9% от суммы Максимального ХП всех союзников!",
    "skills": {
      "basic": "Сто ракет на старт! (Базовая): Взрывная атака (Blast — бьёт 3 цели сразу!) от Max HP Трибби (+1 SP).",
      "skill": "Куда же делись подарки? (Навык): Включает «Откровение» на 3 хода, повышая Пробитие всех типов сопротивления (All-Type RES PEN) всех союзников на 24%!",
      "ult": "Угадай, кто здесь живёт! (Сверхспособность, 120 энергии): Открывает Зону на 2 хода: все враги получают на +30% больше урона (Vulnerability), а за каждого задетого любой атакой союзника врага самая здоровая цель на поле дополнительно получает Квантовый урон (по 12% Max HP Трибби за каждую задетую цель!).",
      "talent": "Занятая-презанятая Трибби (Талант): Когда любой другой союзник использует Сверхспособность, Трибби немедленно запускает ракетную Бонус-атаку по ВСЕМ врагам (срабатывает по 1 разу на каждого из 3 союзников и перезаряжается при собственной Ульте Трибби!).",
      "technique": "А вот и радость! (Техника): В начале боя сразу активирует «Откровение» (+24% RES PEN) на 3 хода без траты SP!",
      "summon_or_elation": "Генератор энергии от количества попаданий: За каждого врага, задетого любой атакой союзника, Трибби восстанавливает 1.5 ед. энергии (в АоЕ-боях и с Великой Гертой/Касторией её Ульта заряжается за 1 ход!).",
      "traces": "След A2: После Бонус-атаки Таланта урон Трибби увеличивается на 72% (до 3 стаков = +216% Бонуса урона!). След A4: Пока активна Зона, Max HP Трибби повышается на 9% от суммы Max HP ВСЕХ союзников на поле (в пачке с Касторией и Гиациной даёт Трибби +3500 ХП!). След A6: В начале боя восстанавливает 30 энергии."
    },
    "rotation": "Техника перед боем (+24% RES PEN уже активно!) → Трибби мгновенно получает 120 энергии на первой же атаке союзников и жмёт Сверхспособность [Ult] прямо на 0 AV! → Союзники жмут свои Ульты → Трибби запускает 3 АоЕ Бонус-атаки → В свой редкий ход (<95 SPD) жмёт взрывную Базовую атаку [Q] (+1 SP), удерживая свои 3-ходовые баффы практически бесконечно!",
    "tipsAndTraps": "Поскольку базовая скорость Трибби — 96, а 4pc сет «Поэт элегии разрушения» отнимает 8% скорости (делая её скорость в меню 88.3 SPD), вам КАТЕГОРИЧЕСКИ НЕЛЬЗЯ ловить больше 6 единиц скорости в сабстатах реликвий! При <95 SPD сет Поэта даёт ей +32% Крит. шанса, а медленная скорость позволяет её баффам (привязанным к её собственным ходам!) висеть весь цикл без повторной траты SP!",
    "eidolons": {
      "e1": "E1 (ЛУЧШИЙ E1 В ИГРЕ!): Пока активна Зона, все атаки союзников дополнительно наносят Истинный Урон (True DMG) самой здоровой цели на поле в размере 24% от СУММАРНОГО урона, нанесённого по всем врагам (в 5 целей увеличивает урон по главному боссу на +120%!)!",
      "e2": "E2: Дополнительный урон Зоны увеличивается до 120% и наносит ещё 1 дополнительный тик.",
      "e4": "E4: Пока активно «Откровение», все союзники игнорируют 18% Защиты врагов.",
      "e6": "E6: После Ульты Трибби сразу запускает Бонус-атаку, а урон всех её Бонус-атак увеличивается на 729%!",
      "rec": "На E0 с конусом «Танцуй! Танцуй! Танцуй!» S5 — королева 0-циклов; её E1 считается сильнейшим E1 в истории Honkai: Star Rail."
    },
