    "uniqueMechanic": "Мидей (3.1) — бессмертный Мнимый берсерк Разрушения, который НЕ ТРАТИТ Очков Навыков (0 SP)! Набрав 100 очков Заряда от потери ХП, он входит в состояние «Кровной Мести» (Vendetta): его Макс. ХП увеличивается на 50%, его Защита обнуляется до 0 (чтобы враги били по его ХП сильнее и быстрее заряжали его счётчик!), он получает полный иммунитет к контролю и до 3 раз НЕ МОЖЕТ УМЕРЕТЬ! В «Кровной Мести» он автоматически использует «Короли убивают королей», а на 150 очках Заряда мгновенно получает внеочередной ход и обрушивает «Богоубийство создаёт богов» (280% Max HP урона!). А его След A6 за каждые 100 ХП свыше 4000 (вплоть до 8000 ХП ДО БОЯ) дарит ему колоссальные +48% Крит. шанса!",
    "skills": {
      "basic": "Клятва пути (Базовая): Мнимый урон от Max HP.",
      "skill": "Смерть не знает преград / Короли убивают королей / Богоубийство создаёт богов (Навык): НЕ ТРАТИТ SP! Потребляет 50%/35% текущего ХП Мидея и бьёт 3 цели. На 150 Заряда автоматически запускает внеочередной ядерный удар «Богоубийство создаёт богов»!",
      "ult": "Трон из костей (Сверхспособность, 160 энергии): Восстанавливает 20% Max HP, даёт +20 Заряда, наносит взрывной Мнимый урон и накладывает Насмешку (Taunt) на 2 хода, указывая цель для следующего «Богоубийства».",
      "talent": "Кровь за кровь (Талант): За каждый 1% потерянного ХП получает 1 Заряд. На 100 Заряда входит в «Кровную Месть» (+50% Max HP, 100% продвижение хода и бессмертие). На 150 Заряда получает мгновенный дополнительный ход для «Богоубийства»!",
      "technique": "Клетка сломанных копий (Техника): Притягивает и провоцирует врагов, а на старте боя сразу даёт +50 Заряда.",
      "summon_or_elation": "Авто-бой в Кровной Мести: В стойке Мидей бьёт автоматически, но вы сами направляете его главный удар «Богоубийство» туда, куда нажали его Сверхспособность!",
      "traces": "След A2: В состоянии «Кровной Мести» Мидей не выходит из стойки при смертельном ударе (до 3 раз за бой!). След A4: Полный иммунитет к дебаффам контроля в «Кровной Мести». След A6 (Окровавленный хитон): В начале боя за каждые 100 ед. Max HP Мидея свыше 4000 (максимум при 8000 HP ДО БОЯ!) повышает его Крит. шанс на 1.2% (до +48% КШ!), входящее лечение на 0.75% (до +30%) и коэффициент набора Заряда от атак врагов на 2.5% (до +100%)!"
    },
    "rotation": "Техника перед боем (+50 Заряда) → Ход 1 (135 SPD): Навык [E] (+50 Заряда = вход в «Кровную Месть» и 100% продвижение!) → Авто-навык «Короли убивают королей» → Воскресенье (134 SPD) тянет Мидея на 100% → Ещё один навык + Сверхспособность [Ult] → Внеочередное «Богоубийство создаёт богов»!",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Критическое правило сборки Мидея: его След A6 проверяет его ХП на старте боя (до применения боевых баффов), поэтому вы ОБЯЗАНЫ иметь ровно 8000+ HP прямо в меню персонажа! И обязательно посмотрите на перекап Крит. шанса: 5% базовых + 48% от Следа A6 (при 8000 HP) + 20% от Воскресенья (или +15% от Кирены / +10% от ГГ Памяти) = вы получаете до +68% Крит. шанса в бою! Поэтому в меню Мидею нужно всего 32% Крит. шанса (или 20% КШ, если на нём сет Долгоживущего Ученика)! 2) Точный контроль Крит. шанса по Prydwen: ВАЖНЕЙШИЙ КАП МИДЕЯ ПО PRYDWEN: его След A6 при 8000 HP в меню даёт ему +48% Крит. шанса прямо в бою! Если в отряде стоит Воскресенье (+20% КШ) или Кирена (+15% КШ), вы получаете до +68% скрытого КШ! Поэтому в меню Мидею нужно собрать СТРОГО НЕ БОЛЕЕ 32% Крит. шанса (или 16% КШ с 4pc Учеником)! 3) Оптимальный спидтюнинг: 135 SPD в меню под схему «-1 SPD» с Воскресеньем (134 SPD) для 4 ударов в 0-м цикле.",
