      "e2": "E2: В «Кровной Мести» все атаки Мидея игнорируют 15% Защиты врагов, а 40% любого входящего в Мидея исцеления конвертируется напрямую в Заряд (до 40 Заряда за хил Гиацины/Лочи!).",
      "e4": "E4: +30% Крит. урона и самоисцеление на 10% Max HP при каждом получении удара от врага.",
      "e6": "E6: Входит в «Кровную Месть» сразу с 0-й секунды боя, а порог для «Богоубийства» снижается со 150 до 100 Заряда!",
      "rec": "Бесплатный ивентовый конус «Ниндзя-запись: Охота за звуком» (`🎉 ИВЕНТ S5`) сидит на нём почти как сигна! E1 и E2 делают его неудержимым в любом режиме."
