    "uniqueMechanic": "Великая Герта (3.0) — настоящая форма гения №83, требующая второго персонажа Эрудиции в отряде (Анакса, Яшма, Химеко • Нова, Аргенти или Сервал): при наличии 2 Эрудитов её След A4 раздаёт ВСЕМУ ОТРЯДУ +80% Крит. урона и удваивает скорость набора стаков «Интерпретации» (до 42 стаков на враге)! Кроме того, за каждого врага, по которому попадает ЛЮБОЙ союзник, Великая Герта восстанавливает по 3 ед. Энергии (минимум за 3 цели = +9..+15 энергии с каждой АоЕ-атаки союзника!). А её Сверхспособность автоматически переносит максимальные 42 стака «Интерпретации» на главного босса, продвигает ход Герты на 100% и заряжает усиленный Навык «У меня есть смелая идея»!",
    "skills": {
      "basic": "Это что, всё? (Базовая): Ледяной урон + стаки «Интерпретации».",
      "skill": "Широта взглядов / У меня есть смелая идея (Навык / Усиленный): Обычный расширяет радиус от 1 цели к 3 и затем ко всем 5 врагам. Усиленный Навык (после Ульты) поглощает до 42 стаков «Интерпретации» на главной цели, получая огромный бонус множителя за каждый стак (удвоенный при 2 Эрудитах в пачке!)!",
      "ult": "Сказали же — это магия! (Сверхспособность, 220 энергии): Переставляет самое большое число стаков «Интерпретации» на элитного босса, наносит АоЕ Ледяной урон, повышает ATK Герты на 80% и немедленно продвигает её действие на 100%!",
      "talent": "Отдай сюда (Талант): Враги входят в бой с 1 стаком «Интерпретации» (или 25 стаками на элитнике). Каждая атака любого союзника накладывает стаки «Интерпретации» (до 42).",
      "technique": "Посмотрим в зеркало (Техника): Отмечает 3 сундука на карте мира, даёт +60% ATK на 2 хода и наносит огромный урон в Виртуальной Вселенной.",
      "summon_or_elation": "Командный генератор энергии (След A2): Любая атака союзника заливает Великой Герте по 3 энергии за каждую задетую цель (минимум 9 энергии за удар даже в 1 босса!).",
      "traces": "След A2: +3 энергии за каждого задетого союзником врага (минимум 3 цели учитываются всегда = минимум +9 энергии с любого удара!). След A4: Если в отряде 2+ персонажа Эрудиции, все союзники получают +80% Крит. урона, атаки накладывают больше стаков, а множитель за стак удваивается! След A6: За каждый наложенный стак «Интерпретации» Великая Герта получает стак «Ответа» (до 99 стаков = +99% урона Сверхспособности и +50% урона усиленного Навыка на 42 стаках)."
    },
    "rotation": "Техника перед боем → Второй Эрудит (Анакса / Яшма) и Трибби/Гиацина бьют по всем врагам (настакивая 42 «Интерпретации» и заливая Герте 220 энергии) → Ход Герты: Навык [E] → Сверхспособность [Ult] (переносит 42 стака на босса и даёт 100% продвижение хода!) → Усиленный Навык «У меня есть смелая идея» [E]!",
    "tipsAndTraps": "Почему Великой Герте ставят верёвку на ATK%, несмотря на Ульту в 220 энергии? Потому что её След A2 даёт фиксированные +9..+15 энергии с КАЖДОЙ атаки Анаксы, Трибби, Гиацины или Линши! И обязательно ставьте ей планарку «Идзумо» (+12% Крит. шанса при наличии второго Эрудита в отряде): с 88% КШ в меню у неё в бою будет ровно 100% КШ под её собственные +80% Крит. урона!",
    "eidolons": {
      "e1": "E1: Усиленный Навык учитывает дополнительно +50% от стаков на главной цели и соседях, а после сброса стаков сразу оставляет на враге 15 стаков «Интерпретации» (вместо 1)!",
      "e2": "E2 (ОГРОМНЫЙ СПАЙК!): Входит в бой сразу с 1 стаком «Вдохновения» (усиленный Навык с 1-го хода!), Ульта даёт ДВА стака «Вдохновения» вместо одного, а после каждого усиленного Навыка действие Герты продвигается на 35%!",
      "e4": "E4: Скорость всех персонажей Эрудиции в отряде повышается на 12%.",
      "e6": "E6: +20% Ледяного RES PEN и до +400% дополнительного множителя Сверхспособности в соло-цель.",
      "rec": "Королева Чистого Вымысла и АоЕ-боссов на E0S1 (сигна даёт бесплатный SP на каждой Ульте!)."
    },
