    "uniqueMechanic": "Первопроходец (Память, Ледяной, 3.0) — бесплатный 5★ саппорт со всеми 6 Эйдолонами из сюжета Амфореуса! Он призывает очаровательного розового Мемоспрайта «Мема» (Mem, SPD 130). Когда союзники восстанавливают энергию (или призываются мемоспрайты), Мем копит Заряд до 100%. На 100% Заряда Мем немедленно получает ход, продвигает действие выбранного вами главного керри на 100% и вешает на него «Поддержку Мема» на 3 хода: весь урон этого керри (и его мемоспрайта!) дополнительно наносит +28%..+48% Истинного Урона (True DMG, который увеличивается тем сильнее, чем выше макс. энергия керри — у Великой Герты, Юньли и Аргенти доходит до +48–50% True DMG!) + +10% Крит. шанса (E1) + ~48% Крит. урона всему отряду!",
    "skills": {
      "basic": "Оставь это мне! (Базовая): Ледяной урон (+1 SP).",
      "skill": "Я выбираю тебя! (Навык): Призывает Мемоспрайта «Мема» (или лечит Мема на 60% ХП и даёт ему +10% Заряда).",
      "ult": "Вперёд, Мем! (Сверхспособность, 160 энергии): Призывает Мема, мгновенно заливает Мему +40% Заряда и заставляет Мема нанести огромный АоЕ Ледяной урон всем врагам со 100% фиксированным Крит. шансом (на E6)!",
      "talent": "Друзья навеки (Талант): За каждые 10 ед. энергии, восстановленные любым союзником, Мем получает +1% Заряда.",
      "technique": "Воспоминания как снег (Техника): Создаёт зону остановки времени на 10 сек., а на старте боя задерживает всех врагов на 50% и наносит Ледяной урон.",
      "summon_or_elation": "Мемоспрайт «Мем» (SPD 130): На <100% Заряда бьёт врагов лапками («Плохие парни! Беда!») и добирает себе +5% Заряда; на 100% Заряда позволяет вам вручную выбрать союзника для 100% продвижения действия и наложения «Поддержки Мема» (True DMG + +10% КШ на 3 хода)!",
      "traces": "След A2: В начале боя продвигает действие ГГ на 30%, а при первом призыве Мем сразу получает +40% Заряда! След A4: Когда Мем бьёт лапками, он сразу получает ещё +5% Заряда. След A6: Если макс. энергия союзника под «Поддержкой Мема» превышает 100, за каждые 10 ед. энергии сверх 100 множитель Истинного Урона вырастает ещё на +2% (до +20% сверху!)."
    },
    "rotation": "Начало боя (30% продвижение ГГ) → Ход 1: Навык [E] (призывает Мема сразу с 50%+ Заряда!) → Союзники жмут навыки и ульты (добирая Мему 100% Заряда уже в начале 0-го цикла!) → Ход Мема (100% Заряда): тянет вашего главного ДД на 100% и даёт Истинный Урон + +10% КШ → Далее ГГ бьёт только Базовой атакой [Q] (+SP!) и жмёт Ульту [Ult] (+40% Заряда Мему)!",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Поскольку все 6 эйдолонов ГГ Памяти бесплатны, запомните: E1 даёт носителю «Поддержки Мема» +10% Крит. шанса (и его мемоспрайту тоже!), а E4 позволяет даже героям с 0 макс. энергии (Кастория, Фаенон, Ахерон, Фэйсяо) получать дополнительные +6% Истинного Урона! Не переберите 100% КШ на вашем ДД с учётом +10% КШ от Мема! 2) Точный контроль Крит. шанса по Prydwen: 0% КШ в реликвиях! Бесплатный Эйдолон E6 даёт Сверхспособности ГГ Памяти и Мему фиксированный 100% Крит. шанс! 3) Оптимальный спидтюнинг: 160.1+ SPD в меню (плюс 30% продвижения на старте боя от Следа A2), чтобы мгновенно призвать Мема и часто заряжать его ход.",
    "eidolons": {
      "e1": "E1 (Бесплатно!): Союзник с «Поддержкой Мема» (и его мемоспрайт!) получает +10% Крит. шанса, а эффект работает одновременно и на хозяине, и на его мемоспрайте!",
      "e2": "E2 (Бесплатно!): Когда действуют мемоспрайты других союзников (Дракон Кастории, Ика Гиацины, Швея Аглаи), ГГ восстанавливает +8 энергии!",
      "e4": "E4 (Бесплатно!): Союзники с 0 макс. энергии (Кастория, Фаенон, Ахерон, Фэйсяо) дают Мему +3% Заряда за применение способностей и получают +6% дополнительного Истинного Урона!",
      "e6": "E6 (Бесплатно!): Крит. шанс Сверхспособности фиксирован на 100%!",
      "rec": "Все E6 бесплатны! Лучший бесплатный саппорт под Касторию, Великую Герту, Фаенона, Мидея и Аглаю."
    },
