      "critRate": "0% КШ в реликвиях! Бесплатный Эйдолон E6 даёт Сверхспособности ГГ Памяти и Мему фиксированный 100% Крит. шанс!",
      "critDmg": "ГЛАВНЫЙ СТАТ ГГ ПАМЯТИ — 200–230%+ Крит. урона в меню! Мем передаёт всем союзникам 12% от Крит. урона ГГ + 24% фиксированно (~50% КУ команде!), а также раздаёт главному керри +28%..+50% Истинного Урона (True DMG) и +10% Крит. шанса (на E1)!",
