      "critRate": "0% КШ в реликвиях — Воскресенье не атакует врагов (кроме редкой базовой атаки), но сам раздаёт выбранному керри +20% Крит. шанса через Талант!",
      "critDmg": "ГЛАВНЫЙ СТАТ БАФФА ВОСКРЕСЕНЬЯ — 210–240%+ Крит. урона в меню! Его Сверхспособность передаёт «Благословенному» керри (и его мемоспрайту/призыву!) 30% от Крит. урона Воскресенья + 12% (при 220% КУ у Воскресенья это +78% КУ вашему ДД + ещё +36% КУ от 4pc сета Сацердоса = +114% Крит. урона!).",
