      "scale": "КАП ФУГИ ПО PRYDWEN — ровно 220% Эффекта пробития В БОЮ! При ≥220% BE в бою её След A4 раздаёт всему отряду максимальные +18%..+24% дополнительного Эффекта пробития при каждом сносе уязвимости (и Экзо-Стойкости!). Поскольку сама Фуга получает +30% BE от Следа A2 и +40% BE от планарки Лотоса Кальпагни в бою, в меню до боя ей нужно собрать всего 150%–190% BE!",
