      "technique": "Шаг по граффити (Техника): Скейтборд в мире; на старте боя снимает 30 радужной стойкости со всех врагов и заливает +10 энергии.",
      "summon_or_elation": "Идеальная пара с Фугой: Экзо-стойкость Фуги удваивает количество пробитий за волну, позволяя Раппе всегда бить 10-стаковым сюрикеном!",
      "traces": "След A2: При пробитии элитного врага даёт +2 стака Заряда и +10 энергии! След A4: 3-й удар усиленной Базовой атаки дополнительно наносит 60% урона Суперпробития. След A6: За каждые 100 ATK свыше 2400 (максимум при 3200 ATK!) повышает получаемый пробитыми врагами урон Пробития на 1% (до +8%, плюс базовые 2% = +10% уязвимости к пробитию!)."
