    "uniqueMechanic": "Юньли (2.4) имеет двухсекционную шкалу Энергии (120 + 120 = 240 ед.) и механику Идеального Парирования («Блок»): если вы нажимаете её Сверхспособность (за 120 энергии) ПРЯМО ПЕРЕД ХОДОМ ВРАГА, Юньли накладывает на всех врагов Насмешку, получает иммунитет к контролю и при ударе врага выпускает сокрушительную Контратаку «Интуитивное: Истребление» (взрыв по 3 целям + 6 случайных отскоков со +100% Крит. урона, которая считается ОДНОВРЕМЕННО и Сверхспособностью, и Бонус-атакой!).",
    "skills": {
      "basic": "Сальто к солнцу (Базовая): Физический урон 1 цели.",
      "skill": "Дрожащий клинок (Навык): Исцеляет Юньли от её ATK и наносит взрывной Физический урон 3 целям.",
      "ult": "Клинок Земли и Неба (Сверхспособность, тратит 120 из 240 энергии): Встаёт в стойку «Блока» до конца следующего хода любого союзника или врага, провоцирует всех врагов и даёт +100% Крит. урона на следующую Контратаку! При получении удара в «Блоке» бьёт «Интуитивным: Истреблением» (3 цели + 6 отскоков)!",
      "talent": "Вспышка кузни (Талант): Когда Юньли атакуют, она получает +15 энергии и немедленно отвечает взрывной Контратакой по 3 целям.",
      "technique": "Защита превыше атаки (Техника): В начале боя при получении или нанесении удара сразу запускает бесплатное «Интуитивное: Истребление» со +80% урона!",
      "summon_or_elation": "Страховка от промаха (След A2): Даже если вы нажали Ульту, а враг не ударил (например, наложил бафф на себя), в следующий раз гарантированно сработает усиленное «Истребление» без потерь!",
      "traces": "След A2: Чередует гарантированный прок «Истребления», если прошлый Блок не поймал прямой удар. След A4: В стойке «Блока» полный иммунитет к контролю и -20% входящего урона. След A6: При проведении Контратаки ATK Юньли повышается на +30% на 1 ход."
    },
    "rotation": "Поставьте Юньли во 2-й или 3-й слот отряда (чтобы ловить взрывные АоЕ врагов!) → Следите за шкалой ходов врагов слева: как только ход агрессивного босса (например, Хулэя) подходит вплотную, нажимайте Сверхспособность Юньли [Ult] (120 энергии) → Мгновенное Парирование «Интуитивное: Истребление»!",
    "tipsAndTraps": "Базовая скорость Юньли — 94! Это значит, что с 4pc сетом «Поэт элегии разрушения» её скорость в меню падает до 86.5 SPD (`<95`), и она получает бесплатные +32% Крит. шанса! Поскольку на самой Ульте у неё встроены +100% Крит. урона, доведите её Крит. шанс до 100% в бою.",
