    "uniqueMechanic": "Цзяоцю (2.4) — лучший сигнатурный напарник Ахерон и сильнейший дебаффер уязвимости к Сверхспособностям! Он накладывает стаки «Пепельного Жара» (Ashen Roast, до 5 стаков = +35% получаемого врагами урона от всех источников + ещё +15% получаемого урона от Сверхспособностей внутри Зоны = суммарно +50% Vulnerability!). А его Зона Хот-пота (всего 100 энергии!) автоматически накладывает стак дебаффа КАЖДЫЙ РАЗ, когда любой враг совершает ход (до 6 раз за Ульту), позволяя Ахерон набирать 9 лепестков Сверхспособности прямо во время ходов боссов и мобов!",
