      "basic": "Огонь в сердце (Базовая): Огненный урон + 1 стак «Пепельного Жара» (+1 SP).",
      "skill": "Пряный натиск (Навык): Взрывной урон по 3 целям + 2 стака «Пепельного Жара» на главную цель.",
      "ult": "Котёл армейских хитростей (Сверхспособность, 100 энергии!): Уравнивает стаки «Пепельного Жара» на всех врагах до максимума на поле и открывает Зону на 3 хода: +15% уязвимости врагов к урону Сверхспособностей и автоматическое наложение стака дебаффа при каждом ходе врага (6 срабатываний)!",
      "talent": "Пятикратная горечь (Талант): На 5 стаках «Пепельного Жара» все враги получают +35% урона от любых атак И одновременно горят мощным Огненным DoT.",
      "technique": "Пламя хаоса (Техника): В начале боя создаёт зону и вешает 1 стак «Пепельного Жара» на всех врагов.",
      "summon_or_elation": "Авто-перенос стаков на новых врагов (След A6): Пока активна Зона, все новые волны врагов входят в бой сразу с наложенным «Пепельным Жаром»!",
      "traces": "След A2: В начале боя сразу восстанавливает +15 энергии (позволяет нажать Ульту с 1-го же Навыка!). След A4: За каждые 15% EHR свыше 80% повышает ATK Цзяоцю на 60% (вплоть до +240% ATK при 140% EHR в меню!). След A6: Враги, входящие в бой во время Зоны, сразу получают стаки «Пепельного Жара»."
