    "uniqueMechanic": "Светлячок (2.3) — эталонный драйвер Суперпробития: её обычный Навык заливает ровно 60% макс. энергии, а Сверхспособность переводит броню СЭМ в режим «Полного Сгорания» (Complete Combustion): она получает 100% продвижение действия, +60 плоской Скорости (разгоняясь до 210–225+ SPD для 4 действий за одну стойку Ульты!), +50% Эффективности пробития уязвимости, +20% получаемого врагами урона Пробития и способность КАЖДЫМ усиленным Навыком имплантировать Огненную уязвимость на главную цель и выжигать полоски стойкости 3 врагам со своим встроенным Суперпробитием (50% от Следа A4 + Суперпробитие Фуги/Георгины/ГГ Гармонии)!",
    "skills": {
      "basic": "Пламенный импульс (Усиленная в Ульте): Исцеляет 20% ХП и бьёт 1 цель.",
      "skill": "Пиро-протокол / Рассечение созвездий DHGDR (Навык / Усиленный): Обычный тратит 40% ХП и заливает 60% макс. энергии (144 энергии за 1 кнопку!). Усиленный в Ульте исцеляет 25% ХП, имплантирует Огненную уязвимость на 2 хода и наносит гигантский урон Суперпробития по 3 целям!",
      "ult": "СЭМ: Полное Сгорание (Сверхспособность, 240 энергии): 100% продвижение хода, +60 Скорости, +50% эффективности пробития и +20% Break Vulnerability до конца таймера «Сгорания» (70 SPD на шкале ходов).",
      "talent": "Пиро-ядро хризалиды (Талант): До +40% снижения входящего урона и +30% Сопротивления эффектам в стойке Ульты; если в начале боя энергия <50%, сразу поднимает её до 50%.",
      "technique": "Метеоритный удар Δ (Техника): Прыжок в воздухе; на старте каждой волны накладывает Огненную уязвимость на ВСЕХ врагов на 2 хода и бьёт по стойкости!",
      "summon_or_elation": "Конверсия Атаки в Пробитие (След A6): За каждые 10 ед. ATK свыше 1800 Светлячок получает +0.8% Эффекта пробития БЕЗ ВСЯКОГО КАПА!",
      "traces": "След A2: В режиме «Полного Сгорания» атаки по врагам без Огненной уязвимости всё равно снимают 55% стойкости. След A4: При Эффекте пробития в бою ≥200% / ≥360% атаки по пробитым врагам наносят 35% / 50% собственного урона Суперпробития! След A6: Конвертирует всю ATK свыше 1800 в Эффект пробития (10 ATK = 0.8% BE)."
    },
    "rotation": "Техника перед боем (все враги с Огненной уязвимостью, энергия 50%!) → Ход 1: Обычный Навык [E] (+60% энергии = 100% Ульты!) → Мгновенная Сверхспособность [Ult] (100% продвижение хода!) → 4 хода подряд в стойке жмёт Усиленный Навык [E]!",
    "tipsAndTraps": "Два важнейших порога Светлячка в бою: 1) 210+ Скорости в Ульте (даёт 3 дополнительных хода внутри одного таймера «Полного Сгорания» + 1 мгновенный ход = 4 усиленных Навыка за Ульту!). С Жуань Мэй или Георгиной (+10% SPD = +10.4) и планаркой Лотоса Кальпагни (+6% SPD = +6.24) вам нужно собрать в меню ровно 154 Скорости (154 + 16.64 + 60 от Ульты = 230.6 SPD в бою, что позволяет сделать 4 действия даже внутри 0-го цикла Зала Забвения!). 2) 360%+ Эффекта пробития в бою для капа Следа A4 — поэтому ставьте Тело и Сферу строго на ATK%!",
    "eidolons": {
      "e1": "E1 (УБИРАЕТ ТРАТУ SP!): Усиленный Навык в режиме «Полного Сгорания» НЕ ТРАТИТ Очков Навыков (0 SP!) и дополнительно игнорирует 15% Защиты врагов (вместе с 4pc Кавалерией = 40% игнора DEF)!",
      "e2": "E2 (ВТОРОЙ ХОД ПРИ ПРОБИТИИ!): Когда Усиленный Навык пробивает уязвимость ИЛИ убивает врага, Светлячок получает МГНОВЕННЫЙ ДОПОЛНИТЕЛЬНЫЙ ХОД (КД 1 ход)! С Экзо-Стойкостью Фуги срабатывает практически на каждом ходу!",
      "e4": "E4: В стойке Ульты Сопротивление эффектам повышается ещё на +50% (100% иммунитет к любому контролю!).",
      "e6": "E6: В стойке Ульты даёт +20% Огненного RES PEN и ещё +50% Эффективности пробития уязвимости!",
      "rec": "E1 и E2 Светлячка — легендарная комбинация, которая превращает её с Фугой, Георгиной и Линшой в вечный двигатель дополнительных ходов без траты SP."
    },
    "synergyPartners": [
      "fugue",
      "the_dahlia",
      "lingsha",
      "ruan_mei",
      "trailblazer_harmony"
    ],
    "rarity": 5,
    "statWhy": {
      "spd": "ГЛАВНЫЙ БРЕЙКПОИНТ СВЕТЛЯЧКА ПО PRYDWEN — 210+ SPD В УЛЬТЕ (или 225 SPD для 4 действий в 0-м цикле)! Сверхспособность даёт ей +60 плоской Скорости: чтобы получить 210+ SPD в Ульте, соберите 150–154 SPD в меню (с Жуань Мэй / Георгиной +10% SPD и Лотосом Кальпагни +6% SPD в бою будет 226+ SPD!).",
      "scale": "СТРОГИЙ КАП СВЕТЛЯЧКА — ≥360% Эффекта пробития В БОЮ! На пороге 360% BE её След A4 включает максимальный 50%-й собственный множитель Суперпробития (а при ≥250% BE сет Кавалерии игнорирует 25% DEF). Поскольку её След A6 конвертирует каждые 10 ATK свыше 1800 в +0.8% Эффекта пробития БЕЗ КАПА, ставьте Тело и Сферу СТРОГО на ATK% (2500+ ATK в меню = +56% бесплатного Пробития)!",
      "err": "Обычный Навык Светлячка всегда восстанавливает ровно 60% от её макс. энергии, поэтому верёвка ставится строго на Эффект пробития%!",
      "critRate": "Ориентир Крит. шанса в меню для Светлячок • СЭМ: 0% КШ, чтобы с учётом боевых бонусов следов, реликвий и саппортов достичь стабильных 100% КШ в бою без перекапа.",
      "critDmg": "Ориентир Крит. урона в меню для Светлячок • СЭМ: 0%+ КУ (в бою разгоняется до 240%+ КУ под баффами отряда)."
    }
