      "ult": "Клятва бездны (Сверхспособность, 140 энергии): АоЕ Квантовый урон всем врагам и усиление следующих 2 Бонус-атак Таланта (+80% множителя!).",
      "talent": "Клык вымогательства (Талант): За каждого задетого Яшмой или «Коллекционером Долгов» врага получает 1 заряд. На 8 зарядах проводит АоЕ Бонус-атаку и получает стаки «Заложенного Актива» (до 50 стаков = +120% Крит. урона и +25% ATK!).",
      "technique": "Видение хищника (Техника): В начале боя сразу даёт 15 стаков «Заложенного Актива» (+36% КУ) и наносит АоЕ урон.",
      "summon_or_elation": "Гениальный трюк с сетом Поэта: Базовая скорость Яшмы — 103. С 4pc сетом «Поэт элегии разрушения» (-8% SPD) её скорость в меню становится 103 * 0.92 = 94.76 SPD (ровно меньше 95!), что активирует +32% Крит. шанса при условии 0 проков скорости в сабстатах!",
      "traces": "След A2: Даёт стаки «Заложенного Актива» при входе врагов в бой и в начале хода «Коллекционера Долгов». След A4: В начале боя продвигает действие Яшмы на 50% (позволяет повесить Контракт первой даже при медленной сборке!). След A6: Каждый стак «Заложенного Актива» также повышает ATK Яшмы на 0.5% (до +25% ATK)."
