    "rotation": "Техника перед боем → Ход 1 (50% продвижение со старта!): Навык [E] на Великую Герту / Линшу / Трибби / Блэйда (+30 SPD цели!) → Далее 2 хода бьёт взрывной Базовой атакой [Q] (+SP!) и спамит усиленными Бонус-атаками!",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Поскольку Яшма заливает «Коллекционеру Долгов» +30 плоской Скорости в бою, ваш главный ДД (например, Великая Герта или Блэйд) может носить сапоги на ATK%/HP% при 105 скорости в меню и всё равно ходить на 135 SPD в бою! 2) Точный контроль Крит. шанса по Prydwen: Доведите КШ до 90–100% в бою (с сетом Поэта +32% и Идзумо +12% это элементарно!), так как её Талант даёт ей огромные +120% Крит. урона в бою! 3) Оптимальный спидтюнинг: Базовая скорость Яшмы — 103. С 4pc сетом Поэта (-8% SPD) её скорость в меню становится 94.76 SPD (ровно <95.0!), что при 0 проков скорости в сабстатах дарит ей +32% Крит. шанса! При этом сама Яшма своим Навыком заливает напарнику («Коллекционеру Долгов») +30 плоской Скорости!",
