    "uniqueMechanic": "Бутхилл (2.2) вызывает врага на «Дуэль» (+30% получаемого целью урона) и копит до 3 пуль «Карманного Преимущества» за пробития или убийства врагов (с Экзо-Стойкостью Фуги он набирает все 3 пули на первом же враге!). С 3 пулями его усиленная Базовая атака «Веерный Выстрел» снимает на +150% больше стойкости и наносит собственный масштабируемый урон Физического Пробития (170% от базового Физического пробития, которое в игре самое сильное и масштабируется от Макс. ХП самого босса!) ДАЖЕ ПО УЖЕ ПРОБИТОМУ БОССУ, а Сверхспособность имплантирует Физическую уязвимость на 2 хода и задерживает босса на 40%!",
    "skills": {
      "basic": "Шпора в череп / Веерный выстрел (Усиленная в Дуэли): 6 выстрелов с револьвера с +50%..+150% урона по стойкости и взрывом Таланта по пробитым врагам.",
      "skill": "Танго шипящего свинца (Навык): Начинает «Дуэль» (Провокация + цель получает на 30% больше урона от Бутхилла) и заряжает «Веерный выстрел».",
      "ult": "Закатное родео пыльного дьявола (Сверхспособность, 115 энергии): Имплантирует Физическую уязвимость на 2 хода, наносит Физический урон и задерживает действие босса на 40%!",
      "talent": "Пять пуль в барабане (Талант): Пробитие или убийство цели в Дуэли даёт пули «Карманного Преимущества» (до 3 стаков, сохраняются между боями!). Наносит огромный дополнительный урон Пробития по пробитым целям.",
      "technique": "Улыбка 3-9-х (Техника): Первое применение Навыка в бою автоматически имплантирует Физическую уязвимость на цель на 2 хода!",
      "summon_or_elation": "Синергия с Воскресеньем / Броней и Фугой: Схема -1 SPD с Воскресеньем/Броней + Экзо-Стойкость Фуги позволяет Бутхиллу сносить две полоски босса за 0 AV!",
      "traces": "След A2: Конвертирует Эффект пробития в +30% Крит. шанса и +150% Крит. урона (кап при 300% BE в бою). След A4: В Дуэли Бутхилл получает на 30% меньше урона от всех остальных врагов на поле. След A6: Получение пули «Карманного Преимущества» восстанавливает +10 энергии (работает даже сверх 3 пуль!)."
    },
    "rotation": "Техника перед боем → Ход 1: Навык [E] (Дуэль + Физический имплант) + Веерный выстрел [Q] → Воскресенье / Броня тянет Бутхилла на 100% → Сверхспособность [Ult] + Веерный выстрел [Q] (снос обеих полосок стойкости босса с Фугой!).",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Не собирайте Бутхиллу криты или атаку в реликвиях! 95% его урона зависит ТОЛЬКО от Эффекта пробития и Скорости, поэтому надевайте ему Тело и Сферу на HP% или DEF% — тогда в «Дуэли» ни один босс не сможет его пробить! 2) Ключевой порог масштабирования: 250%–300%+ Эффекта пробития в меню (320%+ в бою). 3) Оптимальный спидтюнинг: 160.1+ SPD в меню (в бою 172+ SPD с сигной или Жуань Мэй) для мгновенного настакивания 3 пуль «Карманного Преимущества» и частых «Веерных Выстрелов».",
    "eidolons": {
      "e1": "E1: В начале боя сразу даёт 1 пулю «Карманного Преимущества», а все атаки Бутхилла игнорируют 16% Защиты врагов.",
      "e2": "E2: Получение пули восстанавливает 1 Очко Навыков (SP) и даёт +30% Эффекта пробития на 2 хода!",
      "e4": "E4: Цель в Дуэли получает ещё +12% урона, а Бутхилл получает на 12% меньше урона от неё.",
      "e6": "E6: Взрыв Таланта бьёт также соседние цели на 70% множителя (делает Бутхилла Blast-дамагером!).",
      "rec": "В Иллюзии Конца (Apocalyptic Shadow) в паре с Фугой, Георгиной и Воскресеньем до сих пор ваншотает боссов."
    },
