      "critRate": "След A2 Бутхилла («Призрачный заряд») сам конвертирует его Эффект пробития в +30% Крит. шанса и +150% Крит. урона (кап при 300% BE в бою!). Но поскольку 95% его урона — это Физическое Пробитие, криты в реликвиях ему не нужны (лучше надеть Тело и Сферу на HP%/DEF% для выживания в Дуэли!).",
