    "uniqueMechanic": "Первопроходец (Гармония, 2.2) — бесплатный 5★ пионер Суперпробития: его Сверхспособность включает «Запасного Танцора» на 3 хода, даруя всем союзникам +33% Эффекта пробития (плюс ещё 15% от собственного Эффекта пробития ГГ через E4!) и позволяя наносить колоссальный урон Суперпробития (до +60% бонуса в 1 босса от Следа A2!) по пробитым врагам! Его урон Суперпробития ПОЛНОСТЬЮ СКЛАДЫВАЕТСЯ с Суперпробитием Фуги и Георгины!",
    "skills": {
      "basic": "Этикет свинга (Базовая): Мнимый урон 1 цели (+1 SP).",
      "skill": "Дождь полуденных грошей (Навык, 7 ударов на E6): Бросает шляпу на 7 отскоков, сбривая гигантское количество Мнимой стойкости и восстанавливая кучу энергии (первый Навык в бою бесплатный по SP благодаря E1!).",
      "ult": "Шумный парад фонарей (Сверхспособность, 140 энергии): Наделяет всех союзников статусом «Запасной Танцор» на 3 хода (+33% Эффекта пробития и активация Суперпробития по пробитым врагам!).",
      "talent": "Воздушный танец на весь экран (Талант): Каждый раз, когда уязвимость ЛЮБОГО врага пробивается, ГГ мгновенно восстанавливает +11 ед. энергии!",
      "technique": "А теперь! Солисты! (Техника): В начале боя даёт всему отряду +30% Эффекта пробития на 2 хода.",
      "summon_or_elation": "Суммирование Суперпробития: В без-сустейновых (No-Sustain) 0-циклах со Светлячком или Раппой ставят одновременно ГГ Гармонии + Фугу + Георгину — их три независимых инстанса Суперпробития срабатывают с одного удара!",
      "traces": "След A2: Если на поле 5 / 4 / 3 / 2 / 1 враг, урон Суперпробития от «Запасного Танцора» дополнительно увеличивается на 20% / 30% / 40% / 50% / 60% (в 1 босса — +60% мультипликативно!). След A4: Первый удар Навыка снимает на 100% больше стойкости. След A6: Пробитие уязвимости дополнительно задерживает врага на 30%."
    },
    "rotation": "Техника перед боем → Ход 1: Навык [E] (0 SP благодаря E1 и +25% ERR от E2!) → Сверхспособность [Ult] (включает «Запасного Танцора» + 4pc Часовщика + 24% продвижения DDD!).",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Благодаря бесплатному E4 ГГ передаёт всем союзникам 15% от своего общего Эффекта пробития в бою (при 300% BE у ГГ это +45% BE + 33% от Ульты + 30% от 4pc Часовщика = +108% Эффекта пробития всему отряду!). 2) Ключевой порог масштабирования: Чем больше Эффекта пробития у ГГ Гармонии (220%+ в меню, 300%+ в бою), тем больше Пробития он раздаёт всей команде: его бесплатный Эйдолон E4 передаёт всем союзникам 15% от общего Эффекта пробития самого ГГ (плюс +33% от Ульты и +30% от 4pc Часовщика = свыше +105% BE всему отряду!). 3) Оптимальный спидтюнинг: 160.1+ SPD в меню для быстрого отката Ульты и спама конусом «Танцуй! Танцуй! Танцуй!» (24% продвижения команды).",
    "eidolons": {
      "e1": "E1 (Бесплатно!): Первое применение Навыка в бою возвращает 1 Очко Навыков (SP)!",
      "e2": "E2 (Бесплатно!): В первые 3 хода боя Восстановление энергии (ERR) ГГ повышается на +25%!",
      "e4": "E4 (Бесплатно!): Повышает Эффект пробития всех остальных союзников на 15% от Эффекта пробития самого ГГ!",
      "e6": "E6 (Бесплатно!): Количество дополнительных отскоков Навыка увеличивается на +2 (итого 7 ударов за 1 Навык!).",
      "rec": "Все E6 бесплатны! Отличный F2P-напарник для Светлячка, Раппы и Бутхилла (если основной ГГ не занят на Пути Памяти или Радости)."
    },
