      "scale": "Чем больше Эффекта пробития у ГГ Гармонии (220%+ в меню, 300%+ в бою), тем больше Пробития он раздаёт всей команде: его бесплатный Эйдолон E4 передаёт всем союзникам 15% от общего Эффекта пробития самого ГГ (плюс +33% от Ульты и +30% от 4pc Часовщика = свыше +105% BE всему отряду!).",
