    "uniqueMechanic": "Ахерон (2.1) — Эманатор Небытия без шкалы Энергии! Она копит 9 лепестков «Рассечённого Сна» (Slashed Dream, плюс 3 резервных стака «Четырёхкратной Вспышки»): каждый раз, когда ЛЮБОЙ союзник или враг накладывает дебафф в ходе действия (Цзяоцю в ход врагов, Мортенакс Блэйд, Цифер, Пела, Серебряный Волк, сигна Гиацины/Авантюрина), Ахерон получает +1 лепесток! На 9 лепестках она обнажает клинок «Плачущий Багровый Дождь», снижая ВСЕ типы сопротивления врагов на 20% и игнорируя тип уязвимости! А её След A4 требует 2 союзников Небытия на E0 (или всего 1 на E2!) для +160% ИТОГОВОГО мультипликативного множителя урона!",
    "skills": {
      "basic": "Переправа увядших троп (Базовая): Электрический урон.",
      "skill": "Восьмикратная вспышка (Навык): Бьёт 3 цели, даёт +1 лепесток «Рассечённого Сна» (+2 лепестка с сигной S1!) и накладывает «Багровый Узел».",
      "ult": "Плачущий багровый дождь (Сверхспособность, 9 лепестков): Вне очереди ходов обрушивает 3 разреза «Клинка Дождя» (по целям с «Багровым Узлом») + финальный АоЕ-взрыв «Возвращение Стикса», снижая все резисты врагов на 20%!",
      "talent": "Осенние листья багровых крон (Талант): Любое наложение дебаффа в бою даёт 1 лепесток и 1 «Багровый Узел». Во время Ульты игнорирует тип уязвимости и снижает All-Type RES врагов на 20%.",
      "technique": "Четырёхкратное вознесение (Техника): Мгновенно разрубает обычных монстров в открытом мире и Виртуальной Вселенной без входа в бой! В начале волны даёт +1 лепесток.",
      "summon_or_elation": "Условие «Бездна» (След A4): На E0 в отряде ОБЯЗАНЫ быть ещё 2 персонажа Пути Небытия (например, Цзяоцю + Мортенакс Блэйд / Цифер / Пела), чтобы получить 160% базового множителя. На E2 достаточно 1 союзника Небытия (Цзяоцю) + саппорта Гармонии (Воскресенье / Искорка / Трибби)!",
      "traces": "След A2: В начале боя сразу даёт 5 лепестков «Рассечённого Сна» и 5 «Багровых Узлов» (может хранить до 3 избыточных стаков сверх 9!). След A4 («Бездна»): При 1 / 2 других союзниках Небытия весь урон Ахерон составляет 115% / 160% от исходного урона! След A6: Во время Ульты попадание по врагам с «Багровым Узлом» повышает Бонус урона Ахерон на +90% на 3 хода и вызывает 6 дополнительных ударов молнии."
    },
    "rotation": "Вход в бой (6 лепестков со старта с Техникой!) → Быстрый Цзяоцю и второй дебаффер (Мортенакс Блэйд / Цифер / Пела) накладывают дебаффы (9 лепестков!) → Мгновенная Сверхспособность Ахерон [Ult] → Ход Ахерон: Навык [E] (+2 лепестка с S1) → Дебаффы Цзяоцю в ход врагов → Вторая Сверхспособность [Ult]!",
    "tipsAndTraps": "Расчёт Крит. шанса «ДО БОЯ» для Ахерон: 4pc сет «Первооткрыватель мёртвых вод» даёт еще +4% КШ именно в бою (плюс 4% уже видны в меню), а 2pc планарка «Идзумо» даёт +12% КШ в бою при наличии союзника Небытия! Суммарно в бою вы получаете +16% скрытого КШ (а на E1 — ещё +18% КШ = +34% КШ!). Поэтому в меню до боя собирайте ровно 84% КШ на E0 (или 66% КШ на E1)!",
    "eidolons": {
      "e1": "E1: При нанесении урона врагам с дебаффами Крит. шанс повышается на +18% в бою.",
      "e2": "E2 (МЕНЯЕТ КОМАНДООБРАЗОВАНИЕ!): Количество требуемых союзников Небытия для полного 160%-го множителя Следа A4 снижается с 2 до 1 (освобождает слот под Воскресенье/Искорку/Трибби!), а в начале каждого собственного хода Ахерон получает ещё +1 бесплатный лепесток!",
      "e4": "E4: Враги при входе в бой сразу получают +8% уязвимости к урону Сверхспособностей.",
      "e6": "E6: Все атаки Ахерон получают +20% All-Type RES PEN, а её Базовая атака и Навык считаются уроном Сверхспособности и игнорируют тип уязвимости!",
      "rec": "Сигна S1 даёт в 2 раза больше стаков с Навыка Ахерон; в паре с Цзяоцю и Мортенакс Блэйдом/Цифер уверенно чистит эндгейм."
    },
