      "scale": "СТРОГИЙ КАП ЖУАНЬ МЭЙ ПО PRYDWEN — ровно 160% Эффекта пробития В МЕНЮ (= 180% В БОЮ)! Её След A6 за каждые 10% Эффекта пробития свыше 120% даёт отряду по +6% Бонуса урона, достигая ЖЁСТКОГО КАПА +36% (суммарно +68% Бонуса урона на Навыке!) ровно при 180% BE в бою! Поскольку её собственный След A2 даёт всем союзникам (включая саму Жуань Мэй) +20% BE сразу при входе в бой, в меню до боя ей нужно ровно 160% BE!",
      "err": "Верёвка на ERR% (124.4% ERR с Вонваком/Лушакой) + конус «Воспоминания о прошлом» S5 / «Сцепленные шестерни» гарантируют 3-ходовую Ульту (+25% All-Type RES PEN).",
      "critRate": "Ориентир Крит. шанса в меню для Жуань Мэй: 0% КШ, чтобы с учётом боевых бонусов следов, реликвий и саппортов достичь стабильных 100% КШ в бою без перекапа.",
      "critDmg": "Ориентир Крит. урона в меню для Жуань Мэй: 0%+ КУ (в бою разгоняется до 240%+ КУ под баффами отряда)."
