    "uniqueMechanic": "Доктор Рацио (1.6) бросает мощный гипсовый мелок Бонус-атаки (270% ATK) после каждого своего Навыка (100% шанс при 3+ дебаффах на цели) и ещё 2 раза после атак союзников по цели с меткой Сверхспособности! Его Следы A2 и A6 дают ему +15% Крит. шанса, +30% Крит. урона и +50% Бонуса урона при наличии 3–5+ дебаффов на враге. По расчётам Prydwen и официальной базы HSR: 3200+ ATK в меню. Требует минимум 3 дебаффа на цели для 100% шанса вылета мелка Бонус-атаки (и 5 дебаффов для капа +50% Бонуса урона от Следа A6!). 135 SPD в меню для 2 ходов в 0-м цикле.",
    "skills": {
      "basic": "Сила разума (Базовая): Мнимый урон.",
      "skill": "Интеллектуальное акушерство (Навык): Наносит 150% ATK урона и запускает Бонус-атаку Таланта.",
      "ult": "Трёхчастный силлогизм (Сверхспособность, 140 энергии): Наносит 240% ATK урона и вешает «Глупость Мудрецов» (2 следующих удара союзников вызывают Бонус-атаки Рацио!).",
      "talent": "Cogito, Ergo Sum (Талант): Бросает мелок на 270% ATK (базовый шанс 40% + по 20% за каждый дебафф на цели = 100% шанс при 3 дебаффах!).",
      "technique": "Форма идола (Техника): Статуя провоцирует врагов и снижает их Скорость на 15%.",
      "summon_or_elation": "Синергия с Мортенакс Блэйдом / Цифер / Топаз: Дебафферы нового поколения мгновенно закрывают ему кап 5–6 дебаффов с 0-й секунды боя!",
      "traces": "След A2 (Индукция): Даёт до +15% Крит. шанса и +30% Крит. урона (6 стаков за дебаффы на цели). След A4: Навык снижает Сопротивление эффектам цели на 10%. След A6 (Дедукция): При 3+ дебаффах на цели урон Рацио растёт на 10% за каждый дебафф (до +50% Бонуса урона при 5 дебаффах!)."
    },
    "rotation": "Дебаффер накладывает 3+ дебаффа → Ход Рацио: Навык [E] + Бонус-атака → Сверхспособность [Ult] → 2 атаки союзников вызывают ещё 2 Бонус-атаки мелка!",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Не собирайте в меню выше 81% Крит. шанса (81% + 15% от Следа A2 + 4% от 4pc Первооткрывателя = 100% КШ в бою!). 2) Точный контроль Крит. шанса по Prydwen: След A2 («Индукция») даёт Рацио до +15% Крит. шанса и +30% Крит. урона за дебаффы на враге, а 4pc Первооткрыватель — ещё +4% КШ в бою (суммарно +19% КШ!). Поэтому в меню до боя собирайте ровно 81% КШ (= 100% КШ в бою!). 3) Оптимальный спидтюнинг: 135 SPD в меню для 2 ходов в 0-м цикле.",
