    "uniqueMechanic": "Хохо (1.5) даже в патче 4.6 остаётся в SS-тире благодаря тому, что она одновременно является целителем, лучшим в игре чистильщиком дебаффов (до 6 снятий дебаффов за 1 каст Навыка автоматически в начале хода любого союзника или при нажатии его Ульты!) и саппортом Гармонии: её Сверхспособность заливает всем трём союзникам по 20% от их МАКСИМАЛЬНОЙ ЭНЕРГИИ (для Гильгамеша с 360 энергии это +72 ед. энергии, для Аглаи с 350 энергии — +70 ед., для Сэйбер/Юньли — +48 ед.!) и повышает их Силу Атаки на +40% на 2 хода!",
