      "ult": "Хвост: Духовное господство (Сверхспособность, 140 энергии): Восстанавливает всем остальным союзникам 20% от их Макс. Энергии и повышает их ATK на 40% на 2 хода!",
      "talent": "Одержимость: Эфирная метафизика (Талант): Пока активна «Жертвенная Жизнь», в начале хода любого союзника или при применении им Сверхспособности он автоматически исцеляется и снимает с себя 1 дебафф (до 6 раз за один Навык Хохо!) + одновременно лечатся все союзники с ХП ≤50%!",
      "technique": "Демон: Рассеивание зла (Техника): Пугает врагов и снижает их ATK на 25%.",
      "summon_or_elation": "След A6 (Генератор энергии): Каждый раз, когда срабатывает авто-лечение Таланта, Хохо восстанавливает +1 ед. энергии!",
