    "uniqueMechanic": "Топаз (1.4) вешает на главную цель постоянный дебафф «Доказательство Долга» (+50% получаемого целью урона от ВСЕХ Бонус-атак отряда!), а её призывная свинка-копилка «Счетовод» (Numby, 80 SPD) продвигает своё действие на 50% КАЖДЫЙ РАЗ, когда любой союзник бьёт эту цель Бонус-атакой! Все атаки самой Топаз (включая Базовую атаку благодаря Следу A2!) считаются Бонус-атаками и мгновенно разгоняют Счетовода, заряжая стаки Фэйсяо и Зарянки без траты SP!",
