      "basic": "Дефицит... (Базовая): Считается Бонус-атакой (След A2)! Генерирует +1 SP и продвигает Счетовода на 50%.",
      "skill": "Трудности с оплатой? (Навык): Переносит метку «Доказательство Долга» (+50% уязвимости к FUA) и заставляет Счетовода немедленно провести Бонус-атаку (150% ATK).",
      "ult": "Из убытка в прибыль! (Сверхспособность, 130 энергии): Счетовод входит в «Невероятный Подъём» на 2 удара (+150% множителя, +25% Крит. урона и продвижение Счетовода на 50% от ЛЮБЫХ атак союзников!).",
      "talent": "Свинка-рынок?! (Талант): Счетовод (80 SPD) атакует цель с меткой и продвигает свой ход на 50% от каждой Бонус-атаки союзника.",
      "technique": "Явная субсидия (Техника): Счетовод ищет сундуки и свинок-копилок на карте мира и заливает +60 энергии Топаз в бою!",
      "summon_or_elation": "100% FUA-профиль: Поскольку Базовая атака, Навык и сам Счетовод считаются Бонус-атаками, 4pc сет Великого Герцога даёт ей +48% ATK и +20% FUA урона постоянно!",
      "traces": "След A2: Базовая атака Топаз считается Бонус-атакой (двигая Счетовода на 50% даже без траты SP!). След A4: +15% урона по врагам с Огненной уязвимостью. След A6: В стойке Ульты каждая атака Счетовода восстанавливает Топаз +10 энергии."
