    "tipsAndTraps": "1) Главный секрет механики и сборки: Если враг с меткой уже выбран правильно, не тратьте SP на Навык Топаз — её Базовая атака тоже продвигает Счетовода на 50% и генерирует +1 SP для Фэйсяо или Эшвейла! 2) Точный контроль Крит. шанса по Prydwen: 85–90% КШ в меню (с планаркой «Идзумо» +12% КШ в паре со вторым Охотником Фэйсяо/Эшвейлом выходит на 100% КШ в бою!). 3) Оптимальный спидтюнинг: 135–143+ SPD в меню, чтобы обгонять основного FUA-керри (Фэйсяо / Эшвейла) и вовремя перевешивать метку «Доказательство Долга» (+50% уязвимости к Бонус-атакам!).",
