    "uniqueMechanic": "Дань Хэн • Пожиратель Луны (1.3) поглощает до 3 Очков Навыков за один ход, усиливая свою Базовую атаку в 7-ударный лазер «Прыжок сквозь скат» (500% ATK по главной цели + 180% соседним, заливает 40 энергии!), а Сверхспособность даёт 2 «Чешуйки» (заменяющие трату SP!). В связке с Искоркой (160+ SPD) и Воскресеньем спокойно спамит 3-SP ударами каждый ход.",
    "skills": {
      "basic": "Лотос иней / Прыжок сквозь скат (3 уровня усиления): На 3-м уровне (3 SP) наносит 7 ударов (с 4-го удара получает +48% КУ от «Рёва» и до +60% урона от Таланта!).",
      "skill": "Драконий гнев (Навык): Усиливает Базовую атаку до 3 раз без завершения хода.",
      "ult": "Лазурный дракон очищает мир (Сверхспособность, 140 энергии): Наносит 300% ATK урона 3 целям и даёт 2 «Обратные Чешуйки» (бесплатные SP для него!).",
      "talent": "Праведное сердце (Талант): Каждый отдельный удар внутри атаки повышает урон на 10% (до 6 стаков = +60% урона к концу хода!).",
      "technique": "Небесный прорыв (Техника): В начале боя даёт +1 «Обратную Чешуйку».",
      "summon_or_elation": "Идеальная пара с Искоркой и Воскресеньем: Искорка закрывает ему всю потребность в SP и скорости.",
      "traces": "След A2: В начале боя восстанавливает +15 энергии. След A4: +35% сопротивления контролю. След A6: По врагам с Мнимой уязвимостью Крит. урон повышается на +24%!"
    },
    "rotation": "Техника (+1 Чешуйка) → Искорка (160.1+ SPD) тянет Пожирателя Луны → Усиленная Базовая атака 3-го уровня [E×3 + Q] → Сверхспособность [Ult] (+2 Чешуйки!).",
    "tipsAndTraps": "1) Главный секрет механики и сборки: На E2 Ульта даёт ему 100% продвижение хода и 3 Чешуйки — поэтому на E2 всегда нажимайте Ульту СТРОГО ПОСЛЕ обычной 3-SP атаки (чтобы получить мгновенную вторую 3-SP атаку подряд!). 2) Точный контроль Крит. шанса по Prydwen: 80–90% КШ в меню (обязательно ≥70% КШ для активации планарки «Звездистая арена» +20% урона Базовой атаки!). 3) Оптимальный спидтюнинг: Базовые 102 SPD с сапогами на ATK% при игре с быстрой Искоркой (160.1+ SPD), которая вытягивает его на 50% и заливает +4 SP для его 3-SP ударов!",
    "eidolons": {
      "e1": "E1: Лимит стаков Таланта увеличен с 6 до 10 (+100% Бонуса урона!).",
      "e2": "E2 (ЗНАМЕНИТЫЙ E2!): Сверхспособность даёт 3 Чешуйки вместо 2 и МГНОВЕННО продвигает ход Пожирателя Луны на 100%!",
      "e4": "E4: Стаки Крит. урона «Рёва» (+48% КУ) сохраняются до конца следующего хода.",
      "e6": "E6: Ульта союзников даёт +20%..+60% Мнимого RES PEN на следующую 3-SP атаку.",
      "rec": "Классический Мнимый гиперкерри под Искорку и Воскресенье."
    },
