      "critRate": "Сама Фу Сюань криты не строит, но её Навык («Матрица Предвидения») раздаёт ВСЕМ СОЮЗНИКАМ +12% Крит. шанса в бою (а на E1 — ещё и +30% Крит. урона всему отряду!)!",
      "scale": "7500–8500+ HP и 1600–1800+ DEF в меню! Поскольку Матрица перехватывает 65% всего входящего по отряду урона на Фу Сюань, высокий пул HP + DEF гарантирует, что она переживёт любой ядерный удар босса и перевернёт своё ХП Талантом при ≤50% HP!",
