      "scale": "3400–3800+ ATK в меню (в бою получает ЕЩЁ +100% ATK от собственного обновлённого Следа A2!).",
      "ehr": "ВАЖНЕЙШИЙ КАП КАФКИ ПО PRYDWEN (Реворк Novaflare 3.4) — ровно ≥75% EHR! Обновлённый След A2 («Пытка») проверяет Шанс попадания эффектов каждого союзника: если EHR союзника ≥75%, Кафка повышает Силу Атаки (ATK) этого союзника на колоссальные +100%! Поэтому теперь и самой Кафке, и её DoT-напарницам (Гисиленсе и Чёрному Лебедю) обязательно собирают ≥75% EHR!",
