    "uniqueMechanic": "Классический Серебряный Волк (1.1) — лучший соло-таргетный дебаффер защиты (-45% DEF от Ульты + -8% DEF от Бага Таланта = -53% среза Защиты!) и имплантер уязвимости (-13% стихийного резиста на 3 хода!). Каждая её атака (даже обычная Базовая атака!) гарантированно накладывает «Баг» (давая стак Ахерон и Рацио на каждом ходу без траты SP!). По расчётам Prydwen и официальной базы HSR: КАП КОНВЕРСИИ ВОЛКА (Реворк Novaflare 3.4): её обновлённый След A6 даёт по +10% Силы Атаки за каждые 10% EHR вплоть до КАПА +50% ATK ровно при 50% EHR! 160.1+ SPD в меню, чтобы ходить первой, имплантировать уязвимость 1-го слота отряда и накладывать АоЕ -45% Защиты Ультой.",
    "skills": {
      "basic": "Системное предупреждение (Базовая): Квантовый урон + 1 Баг Таланта (+1 SP).",
      "skill": "Разрешить изменения? (Навык): Имплантирует уязвимость одной из стихий отряда на 3 хода и снижает All-Type RES цели на 10% (плюс -20% к имплантированной стихии и -3% со Следом A4!).",
      "ult": "Пользователь забанен (Сверхспособность, 110 энергии): Снижает Защиту цели на 45% на 3 хода и наносит 380% ATK Квантового урона!",
      "talent": "Ожидание ответа системы... (Талант): Каждая атака накладывает случайный Баг (-10% ATK, -8% DEF или -6% SPD) на 4 хода.",
      "technique": "Принудительное завершение программы (Техника): В начале боя снимает 20 ед. стойкости со ВСЕХ врагов независимо от типа их уязвимости!",
      "summon_or_elation": "Моно-Квант с Арчером и Искоркой: В отряде Арчер + Рин Тосака / Искорка + Серебряный Волк + Фу Сюань Волк со 100% вероятностью вешает Квантовую уязвимость на любого босса и даёт Арчеру 73% среза защиты (53% Волк + 20% Квантовый сет)!",
      "traces": "След A2 (Реворк Novaflare 3.4): В начале боя восстанавливает 20 энергии и ещё +5 энергии в начале каждого своего хода! След A4: Имплантирует уязвимость стихии 1-го слота отряда (приоритетно!) и снижает резисты на 20%, а Ульта бьёт ВСЕХ ВРАГОВ (АоЕ -45% DEF на всё поле боя!). След A6 (КАП КОНВЕРСИИ 50% EHR): За каждые 10% Шанса попадания эффектов (EHR) Серебряного Волка её Сила Атаки повышается на +10%, вплоть до КАПА +50% ATK при 50% EHR (а при 67% EHR все её дебаффы имеют 100% шанс попадания!)."
    },
    "rotation": "Техника перед боем → Ход 1 (160.1+ SPD): Навык [E] (имплант уязвимости) + Сверхспособность [Ult] (-45% DEF!) → Ходы 2 и 3: Базовая атака [Q] (+SP и наложение Багов!).",
    "tipsAndTraps": "1) Главный секрет механики и сборки: С бесплатным ивентовым конусом «Перед началом тренировочной миссии» (`🎉 ИВЕНТ S5`) и верёвкой на ERR% Серебряный Волк откатывает Сверхспособность за 1 Навык + 1 Базовую атаку! 2) Ключевой порог масштабирования: КАП КОНВЕРСИИ ВОЛКА (Реворк Novaflare 3.4): её обновлённый След A6 даёт по +10% Силы Атаки за каждые 10% EHR вплоть до КАПА +50% ATK ровно при 50% EHR! 3) Оптимальный спидтюнинг: 160.1+ SPD в меню, чтобы ходить первой, имплантировать уязвимость 1-го слота отряда и накладывать АоЕ -45% Защиты Ультой.",
