    "uniqueMechanic": "Лоча (1.1) — абсолютно SP-позитивный целитель (+1 SP каждый ход!) и отличный F2P-драйвер для Кастории и Мидея (если нет Гиацины): его экстренный Навык срабатывает АВТОМАТИЧЕСКИ И БЕСПЛАТНО при падении ХП союзника ≤50% (снимая дебафф), а на 2 «Цветках Бездны» раскрывается Поле Жизни, внутри которого КАЖДАЯ атака любого союзника или мемоспрайта массово исцеляет весь отряд (быстро заряжая Дракона Кастории и Заряд Мидея!)!",
