      "ult": "Желание смерти (Сверхспособность, 100 энергии): Снимает по 1 баффу со всех врагов, наносит АоЕ Мнимый урон и даёт +1 «Цветок Бездны».",
      "talent": "Цикл жизни (Талант): На 2 «Цветках Бездны» создаёт Поле на 2 хода: любая атака союзника лечит его И всех остальных союзников от ATK Лочи (След A4)!",
      "technique": "Милосердие глупца (Техника): В начале боя сразу активирует Поле Жизни на 2 хода!",
      "summon_or_elation": "Лучший альтернативный хилер для Кастории и Мидея: Внутри Поля Лочи каждая атака союзника триггерит массовый хил всех 4 героев и мемоспрайтов, мгновенно заливая заряд «Нового Бутона» Кастории!",
      "traces": "След A2: Навык (включая авто-навык!) снимает 1 ослабление с цели. След A4: Атака любого союзника в Поле дополнительно исцеляет ВСЕХ остальных союзников! След A6: +70% сопротивления дебаффам контроля."
