    "rotation": "Техника перед боем (Поле сразу активно!) → Всю битву бьёт только Базовой атакой [Q] (+1 SP каждый ход!) → Авто-Навык + Сверхспособность [Ult] (держите её наготове и нажимайте сразу после того, как Поле погасло!).",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Не жмите Ульту Лочи, пока Поле Жизни уже активно на земле! Во время активного Поля Лоча не может получать новые «Цветки Бездны» — подождите, пока Поле закончится, и сразу нажмите Ульту + авто-навык, чтобы тут же открыть новое Поле! 2) Ключевой порог масштабирования: 3200+ ATK в меню — в отличие от большинства хилеров Изобилия, лечение Лочи и его Поля Жизни масштабируется от Силы Атаки (ATK%)! 3) Оптимальный спидтюнинг: 160.1+ SPD в меню (с 3★ конусом «Умножение» S5 или 4★ «Равноценный обмен» S5) для максимальной генерации Очков Навыков (+1 SP каждый ход!).",
