      "ult": "Несущий свет (Сверхспособность, 130 энергии): АоЕ Электрический урон (200% ATK) и +3 удара «Повелителю Молний».",
      "talent": "Искоренение праны (Талант): На поле присутствует «Повелитель Молний» (начальные 3 удара, макс. 10 ударов по 66% ATK каждый + 25% соседям; считается и Призывным существом, и Бонус-атакой!).",
      "technique": "Призыв духа (Техника): В начале боя даёт +3 удара «Повелителю Молний» (старт сразу с 6 ударов!).",
      "summon_or_elation": "Идеальная синергия с Воскресеньем и Банановой планаркой: Банановый парк даёт Цзин Юаню +48% Крит. урона, а Воскресенье даёт +80% урона и мгновенно вытягивает Повелителя Молний наверх очереди!",
      "traces": "След A2: При 6+ ударах Повелителя Молний его Крит. урон повышается на +25%! След A4: В начале боя восстанавливает +15 энергии. След A6: Применение Навыка повышает Крит. шанс Цзин Юаня на +10% на 2 хода!"
