    "rotation": "Техника перед боем (6 стаков) → Цзин Юань (135 SPD): Навык [E] (8 стаков) → Воскресенье (134 SPD): Навык [E] + Ульта [Ult] на Цзин Юаня → Мгновенный удар 8-10 стакового Повелителя Молний → Второй ход Цзин Юаня: Навык [E] + Ульта [Ult] (снова 8–10 стаков!).",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Не переберите Крит. шанс! След A6 Цзин Юаня даёт +10% КШ после Навыка, а Воскресенье даёт ещё +20% КШ (суммарно +30% КШ в бою!). Поэтому в меню до боя собирайте ровно 70% Крит. шанса! 2) Точный контроль Крит. шанса по Prydwen: След A6 Цзин Юаня даёт +10% Крит. шанса после Навыка, а Воскресенье даёт ещё +20% КШ (суммарно +30% скрытого КШ!). Поэтому в меню до боя собирайте ровно 70% Крит. шанса (= 100% КШ в бою!). 3) Оптимальный спидтюнинг: 135 SPD в меню под схему «-1 SPD» с Воскресеньем (134 SPD), который продвигает на 100% и самого Цзин Юаня, и «Повелителя Молний»!",
