    "uniqueMechanic": "Яньцин (1.0) после Навыка включает «Связь с Мечом» (+20% Крит. шанса и +30% Крит. урона + 60% шанс Заморозить врага Бонус-атакой!), а его Сверхспособность даёт ЕЩЁ +60% Крит. шанса и +50% Крит. урона (суммарно +80% Крит. шанса и +80% Крит. урона из воздуха!). Единственное условие — он НЕ ДОЛЖЕН потерять ни 1 единицы ХП от удара врага, поэтому в отряде ОБЯЗАН быть щитовик (Дань Хэн • Освободитель Пустошей, Авантюрин или Гепард)!",
    "skills": {
      "basic": "Холодный шип (Базовая): Ледяной урон.",
      "skill": "Дротик железного холода (Навык): Наносит Ледяной урон и активирует «Связь с Мечом» (+20% КШ и +30% КУ) на 1 ход.",
      "ult": "Погоня за ласточкой под дождём (Сверхспособность, 140 энергии): Даёт +60% Крит. шанса (и +50% Крит. урона при активной Связи с Мечом!) и бьёт 1 цель на 350% ATK!",
      "talent": "Единение с клинком (Талант): Снижает агро, даёт +20% КШ / +30% КУ и 60% шанс провести Бонус-атаку с Заморозкой. Спадает, если Яньцин потеряет ХП!",
      "technique": "Истинное мастерство меча (Техника): +30% урона по врагам с ХП ≥50%.",
      "summon_or_elation": "Идеальный щитовик — Дань Хэн PT (3.6) или Авантюрин: Их непробиваемые щиты гарантируют, что Яньцин никогда не потеряет «Связь с Мечом»!",
      "traces": "След A2: +30% ATK Ледяного доп. урона по врагам с Ледяной уязвимостью. След A4: Пока активна «Связь с Мечом», Effect RES +20%. След A6: При нанесении крит. удара Скорость Яньцина повышается на +10% на 2 хода!"
    },
    "rotation": "Щит союзника → Навык Яньцина [E] → Сверхспособность [Ult] (строго при активной Связи с Мечом!) → Навык [E].",
    "tipsAndTraps": "1) Главный секрет механики и сборки: Защита от перекапа КШ №1 в игре: Талант (+20% КШ) + Ульта (+60% КШ) = +80% Крит. шанса в бою! Поэтому в меню ДО БОЯ у Яньцина должно быть СТРОГО НЕ БОЛЬШЕ 20% Крит. шанса! 2) Точный контроль Крит. шанса по Prydwen: ЗАЩИТА ОТ ПЕРЕКАПА №1 В ИГРЕ: при активной «Связи с Мечом» Талант Яньцина даёт +20% Крит. шанса, а его Сверхспособность — ещё +60% Крит. шанса (суммарно +80% КШ в бою!). Поэтому в меню до боя собирайте СТРОГО НЕ БОЛЕЕ 20% Крит. шанса! 3) Оптимальный спидтюнинг: 135 SPD в меню (След A6 сам даёт ему ещё +10% Скорости в бою при крит. ударе!).",
    "eidolons": {
      "e1": "E1: +60% ATK доп. Ледяного урона по замороженным целям.",
      "e2": "E2: Пока активна «Связь с Мечом», Восстановление энергии (ERR) повышается на +10%.",
      "e4": "E4: При ХП ≥80% получает +12% Пробития Ледяного резиста (Ice RES PEN).",
      "e6": "E6: Убийство врага под баффами Ульты продлевает их длительность на +1 ход.",
      "rec": "Требует строгого щитовика (Дань Хэн PT / Авантюрин / Гепард)."
    },
