      "critRate": "ЗАЩИТА ОТ ПЕРЕКАПА №1 В ИГРЕ: при активной «Связи с Мечом» Талант Яньцина даёт +20% Крит. шанса, а его Сверхспособность — ещё +60% Крит. шанса (суммарно +80% КШ в бою!). Поэтому в меню до боя собирайте СТРОГО НЕ БОЛЕЕ 20% Крит. шанса!",
      "critDmg": "Все роллы вкладывайте в Крит. урон (220%+ в меню + +80% КУ от Таланта и Ульты в бою!).",
