    "uniqueMechanic": "Первопроходец (Сохранение, 1.0) — бесплатный Огненный танк: его Навык накладывает гарантированную АоЕ Насмешку (Taunt) на всех врагов и снижает входящий урон по всему отряду на 15% (След A2!), а каждое его действие (Базовая атака, Навык и Ульта) вешает на команду лёгкий обновляемый щит! По расчётам Prydwen и официальной базы HSR: 3200+ DEF в меню. 134–143+ SPD в меню для регулярного обновления Насмешки и микро-щитов Таланта.",
