      "traces": "След A2: Навык снижает входящий урон по всем союзникам на 15%. След A4: Усиленная Базовая атака лечит ГГ на 5% Max HP. След A6: Если в начале хода на ГГ есть щит, он получает +15% ATK и +5 энергии."
